      ?ig wm:belongsToInvestor ?inv .
      ?inv wm:investorId ?investorId .
      ?ig wm:investmentGoal ?goalName .
      FILTER(LCASE(STR(?goalName)) = "emergency fund") .
      ?ig wm:progressPct ?progressPct .
    }
    GROUP BY ?investorId
  }
