PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investmentGoal ?description (COUNT(DISTINCT ?rebalance) AS ?rebalanceCount)
WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?invId .
  FILTER(CONTAINS(LCASE(STR(?invId)), "inv-008")) .

  OPTIONAL {
    ?investor wm:hasInvestmentGoal ?goal .
    ?goal rdf:type wm:InvestmentGoal .
    OPTIONAL { ?goal wm:investmentGoal ?investmentGoal . }
    OPTIONAL { ?goal wm:description ?description . }
  }

  OPTIONAL {
    ?investor wm:hasRebalancingAction ?rebalance .
    ?rebalance rdf:type wm:RebalancingAction .
  }
}
GROUP BY ?investmentGoal ?description

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon ?cashFlowTypeLabel (COUNT(DISTINCT ?investor) AS ?investorCount)
WHERE {
  {
    SELECT DISTINCT ?investor ?timeHorizon ?cashFlowType
    WHERE {
      ?investor rdf:type wm:Investor .
      OPTIONAL { ?investor wm:timeHorizon ?timeHorizon . }
      ?cashFlow rdf:type wm:CashFlow .
      ?cashFlow wm:hasCashFlowType ?cashFlowType .
      ?cashFlow wm:cashFlowOfInvestor ?investor .
    }
  }
  OPTIONAL { ?cashFlowType rdfs:label ?cashFlowTypeLabel . }
  BIND(COALESCE(?timeHorizon, "NULL") AS ?timeHorizon)
  BIND(COALESCE(?cashFlowTypeLabel, "NULL") AS ?cashFlowTypeLabel)
}
GROUP BY ?timeHorizon ?cashFlowTypeLabel

