PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segmentLabel ?sectorLabel (COUNT(DISTINCT ?investorId) AS ?investorCount)
WHERE {
  ?holding rdf:type wm:PortfolioHolding .
  ?holding wm:heldByInvestor ?investor .
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .

  OPTIONAL {
    ?holding wm:hasSegment ?segment .
    OPTIONAL { ?segment rdfs:label ?segmentLabelRaw . }
  }
  BIND (COALESCE(?segmentLabelRaw, "NULL") AS ?segmentLabel)

  OPTIONAL {
    ?holding wm:hasSector ?sector .
    OPTIONAL { ?sector rdfs:label ?sectorLabelRaw . }
  }
  BIND (COALESCE(?sectorLabelRaw, "NULL") AS ?sectorLabel)
}
GROUP BY ?segmentLabel ?sectorLabel

