PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segmentLabel (SUM(xsd:decimal(?amount)) AS ?totalCashFlowAmount)
WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .
  FILTER(CONTAINS(LCASE(STR(?investorId)), "inv-017")) .

  OPTIONAL {
    ?investor wm:hasSegment ?segment .
    OPTIONAL { ?segment rdfs:label ?segmentLabel . }
  }

  OPTIONAL {
    ?investor wm:hasCashFlow ?cashFlow .
    ?cashFlow wm:amount ?amount .
  }
}
GROUP BY ?segmentLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTol (COUNT(DISTINCT ?investorId) AS ?investorCount)
WHERE {
  # Investors with Equity holdings
  {
    SELECT DISTINCT ?investorId
    WHERE {
      ?holding rdf:type wm:PortfolioHolding .
      ?holding wm:investmentType ?invType .
      ?holding wm:investorId ?investorId .
      FILTER(LCASE(STR(?invType)) = "equity")
    }
  }
  # Investors with SIP cash flow
  {
    SELECT DISTINCT ?investorId
    WHERE {
      ?cash rdf:type wm:CashFlow .
      ?cash wm:type ?cashType .
      ?cash wm:investorId ?investorId .
      FILTER(LCASE(STR(?cashType)) = "sip")
    }
  }
  # Link to investor to get risk tolerance
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:riskTolerance ?riskTol . }
  BIND(COALESCE(?riskTol, "NULL") AS ?riskTol)
}
GROUP BY ?riskTol

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon ?sector (COUNT(DISTINCT ?investor) AS ?investorCount)
WHERE {
  ?investor rdf:type wm:Investor .
  OPTIONAL { ?investor wm:timeHorizon ?timeHorizon . }
  ?ph rdf:type wm:PortfolioHealth ;
      wm:healthOfInvestor ?investor ;
      wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) > 50) .
  ?alloc rdf:type wm:SectorAllocation ;
         wm:allocationOfInvestor ?investor ;
         wm:allocationPct ?allocPct ;
         wm:sector ?sector .
  FILTER(xsd:decimal(?allocPct) > 0) .
}
GROUP BY ?timeHorizon ?sector

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon (COUNT(DISTINCT ?investor) AS ?investorCount)
WHERE {
  ?investor rdf:type wm:Investor .
  OPTIONAL { ?investor wm:timeHorizon ?timeHorizon . }

  ?alloc rdf:type wm:SectorAllocation ;
         wm:allocationOfInvestor ?investor ;
         wm:allocationPct ?allocPct ;
         wm:sector ?sector .
  FILTER(xsd:decimal(?allocPct) > 0) .
  FILTER(CONTAINS(LCASE(STR(?sector)), "technology")) .

  ?cf rdf:type wm:CashFlow ;
      wm:cashFlowOfInvestor ?investor ;
      wm:type ?cfType .
  FILTER(CONTAINS(LCASE(STR(?cfType)), "deposit")) .
}
GROUP BY ?timeHorizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segmentLabel ?sector (COUNT(DISTINCT ?investor) AS ?investorCount)
WHERE {
  ?investor rdf:type wm:Investor .
  ?ph rdf:type wm:PortfolioHealth ;
      wm:healthOfInvestor ?investor ;
      wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) > 50) .

  ?sa rdf:type wm:SectorAllocation ;
      wm:allocationOfInvestor ?investor ;
      wm:allocationPct ?allocPct ;
      wm:sector ?sector .
  FILTER(xsd:decimal(?allocPct) > 0) .

  OPTIONAL {
    ?investor wm:hasSegment ?segmentObj .
    ?segmentObj rdf:type wm:Segment .
    OPTIONAL { ?segmentObj rdfs:label ?segmentLabel . }
    OPTIONAL { ?segmentObj wm:segment ?segmentLabel . }
  }
  BIND(COALESCE(?segmentLabel, "NULL") AS ?segmentLabel)
}
GROUP BY ?segmentLabel ?sector

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segment (COUNT(DISTINCT ?investor) AS ?investorCount)
WHERE {
  ?investor rdf:type wm:Investor .

  OPTIONAL { ?investor wm:segment ?segment . }
  BIND(COALESCE(?segment, "NULL") AS ?segment)

  ?holding rdf:type wm:PortfolioHolding ;
           wm:investmentType ?invType ;
           wm:heldByInvestor ?investor .
  FILTER(LCASE(STR(?invType)) = "etf")

  ?scenarioReb rdf:type wm:ScenarioRebalancing ;
               wm:scenario ?scenario ;
               wm:scenarioRebalancingOfInvestor ?investor .
  FILTER(LCASE(STR(?scenario)) = "bull market")
}
GROUP BY ?segment

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segment (COUNT(DISTINCT ?investorId) AS ?investorCount)
WHERE {
  # Investors with a Mutual Fund holding
  {
    SELECT DISTINCT ?investorId
    WHERE {
      ?holding rdf:type wm:PortfolioHolding .
      ?holding wm:investmentType ?invType .
      ?holding wm:investorId ?investorId .
      FILTER(LCASE(STR(?invType)) = "mutual fund")
    }
  }
  # Investors with a Growth investment goal
  {
    SELECT DISTINCT ?investorId
    WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:investmentGoal ?goalType .
      ?goal wm:investorId ?investorId .
      FILTER(LCASE(STR(?goalType)) = "growth")
    }
  }
  # Get segment for each investor
  ?inv rdf:type wm:Investor .
  ?inv wm:investorId ?investorId .
  OPTIONAL { ?inv wm:segment ?segment . }
  BIND(COALESCE(?segment, "NULL") AS ?segment)
}
GROUP BY ?segment

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category ?sector (COUNT(DISTINCT ?investor) AS ?investorCount)
WHERE {
  ?investor rdf:type wm:Investor .
  ?holding rdf:type wm:PortfolioHolding ;
           wm:heldByInvestor ?investor ;
           wm:category ?category ;
           wm:sector ?sector .
  ?ph rdf:type wm:PortfolioHealth ;
      wm:healthOfInvestor ?investor ;
      wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) > 50)
}
GROUP BY ?category ?sector

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (AVG(xsd:decimal(?holdingsPerInvestor)) AS ?avgHoldingsPerInvestor)
       (AVG(xsd:decimal(?netCashFlowPerInvestor)) AS ?avgNetCashFlowPerInvestor)
       (AVG(xsd:decimal(?riskScorePerInvestor)) AS ?avgRiskScore)
WHERE {
  {
    SELECT ?investor ?riskTolerance
           (COUNT(?holding) AS ?holdingsPerInvestor)
           (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlowPerInvestor)
           (MAX(xsd:decimal(?riskScore)) AS ?riskScorePerInvestor)
    WHERE {
      ?investor rdf:type wm:Investor .
      OPTIONAL { ?investor wm:riskTolerance ?riskTolerance . }
      OPTIONAL { ?investor wm:hasHolding ?holding . }
      OPTIONAL {
        ?investor wm:hasCashFlow ?cf .
        ?cf wm:amount ?cfAmount .
      }
      OPTIONAL {
        ?investor wm:hasPortfolioHealth ?ph .
        ?ph wm:riskScore ?riskScore .
      }
    }
    GROUP BY ?investor ?riskTolerance
  }
  BIND(COALESCE(?riskTolerance, "NULL") AS ?riskTolerance)
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (AVG(xsd:decimal(?holdingsCount)) AS ?avgHoldingsPerInvestor)
       (AVG(xsd:decimal(?actionsCount)) AS ?avgRebalancingActionsPerInvestor)
       (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore)
WHERE {
  # Investor with risk tolerance
  ?investor rdf:type wm:Investor .
  OPTIONAL { ?investor wm:riskTolerance ?rt . }
  BIND(COALESCE(?rt, "NULL") AS ?riskTolerance)

  # Holdings count per investor
  {
    SELECT ?investor (COUNT(?holding) AS ?holdingsCount)
    WHERE {
      ?investor rdf:type wm:Investor .
      OPTIONAL { ?investor wm:hasHolding ?holding . }
    }
    GROUP BY ?investor
  }

  # Rebalancing actions count per investor (zero if none)
  {
    SELECT ?investor (COUNT(?action) AS ?actionsCount)
    WHERE {
      ?investor rdf:type wm:Investor .
      OPTIONAL { ?investor wm:hasRebalancingAction ?action . }
    }
    GROUP BY ?investor
  }

  # Risk score per investor
  OPTIONAL {
    ?ph rdf:type wm:PortfolioHealth .
    ?ph wm:healthOfInvestor ?investor .
    ?ph wm:riskScore ?riskScore .
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon 
       (AVG(xsd:decimal(?holdingsCount)) AS ?avgHoldingsPerInvestor) 
       (AVG(xsd:decimal(?rebalanceCount)) AS ?avgRebalancesPerInvestor) 
       (AVG(xsd:decimal(?riskScoreVal)) AS ?avgRiskScore)
WHERE {
  {
    SELECT ?investor ?timeHorizon (COUNT(DISTINCT ?holding) AS ?holdingsCount)
    WHERE {
      ?investor rdf:type wm:Investor .
      OPTIONAL { ?investor wm:timeHorizon ?timeHorizon . }
      OPTIONAL { ?investor wm:hasHolding ?holding . }
    }
    GROUP BY ?investor ?timeHorizon
  }
  {
    SELECT ?investor (COUNT(DISTINCT ?rebalance) AS ?rebalanceCount)
    WHERE {
      ?investor rdf:type wm:Investor .
      OPTIONAL { ?investor wm:hasRebalancingAction ?rebalance . }
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (xsd:decimal(?riskScore) AS ?riskScore)
    WHERE {
      ?investor rdf:type wm:Investor .
      OPTIONAL {
        ?ph rdf:type wm:PortfolioHealth .
        ?ph wm:healthOfInvestor ?investor .
        ?ph wm:riskScore ?riskScore .
      }
    }
    GROUP BY ?investor ?riskScore
  }
  BIND(COALESCE(?riskScore, 0) AS ?riskScoreVal)
}
GROUP BY ?timeHorizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon 
       (AVG(?totalCashFlowAdj) AS ?avgNetCashFlow) 
       (AVG(?avgGoalProgressAdj) AS ?avgGoalProgress) 
       (AVG(?riskScoreAdj) AS ?avgRiskScore)
WHERE {
  ?inv rdf:type wm:Investor .
  ?inv wm:timeHorizon ?timeHorizon .

  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?amount)) AS ?totalCashFlow) WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:amount ?amount .
      ?cf wm:cashFlowOfInvestor ?inv .
    } GROUP BY ?inv
  }
  BIND(COALESCE(?totalCashFlow, 0) AS ?totalCashFlowAdj)

  OPTIONAL {
    SELECT ?inv (AVG(xsd:decimal(?progress)) AS ?avgGoalProgress) WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:progressPct ?progress .
      ?goal wm:belongsToInvestor ?inv .
    } GROUP BY ?inv
  }
  BIND(COALESCE(?avgGoalProgress, 0) AS ?avgGoalProgressAdj)

  OPTIONAL {
    SELECT ?inv (xsd:decimal(?riskScore) AS ?riskScore) WHERE {
      ?ph rdf:type wm:PortfolioHealth .
      ?ph wm:riskScore ?riskScore .
      ?ph wm:healthOfInvestor ?inv .
    } GROUP BY ?inv
  }
  BIND(COALESCE(?riskScore, 0) AS ?riskScoreAdj)
}
GROUP BY ?timeHorizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon
       (AVG(xsd:decimal(?holdingCount)) AS ?avgHoldingsPerInvestor)
       (AVG(xsd:decimal(?cashFlowSum)) AS ?avgNetCashFlowPerInvestor)
       (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore)
WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:timeHorizon ?timeHorizon . }

  OPTIONAL {
    SELECT ?investorId (COUNT(?holding) AS ?holdingCount)
    WHERE {
      ?inv rdf:type wm:Investor .
      ?inv wm:investorId ?investorId .
      OPTIONAL {
        ?inv wm:hasHolding ?holding .
        ?holding rdf:type wm:PortfolioHolding .
      }
    }
    GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cashFlowSum)
    WHERE {
      ?inv2 rdf:type wm:Investor .
      ?inv2 wm:investorId ?investorId .
      OPTIONAL {
        ?inv2 wm:hasCashFlow ?cf .
        ?cf rdf:type wm:CashFlow .
        ?cf wm:amount ?amount .
      }
    }
    GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (AVG(xsd:decimal(?riskScoreVal)) AS ?riskScore)
    WHERE {
      ?inv3 rdf:type wm:Investor .
      ?inv3 wm:investorId ?investorId .
      OPTIONAL {
        ?ph rdf:type wm:PortfolioHealth .
        ?ph wm:healthOfInvestor ?inv3 .
        ?ph wm:riskScore ?riskScoreVal .
      }
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?timeHorizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segmentLabel 
       (AVG(xsd:decimal(?holdingsCount)) AS ?avgHoldingsPerInvestor) 
       (AVG(xsd:decimal(?rebalanceCount)) AS ?avgRebalancePerInvestor) 
       (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore)
WHERE {
  {
    SELECT ?investor ?segmentLabel (COUNT(DISTINCT ?holding) AS ?holdingsCount) (COUNT(DISTINCT ?action) AS ?rebalanceCount) (AVG(xsd:decimal(?riskScoreVal)) AS ?riskScore)
    WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:hasSegment ?segment .
      OPTIONAL { ?segment rdfs:label ?segmentLabel . }

      OPTIONAL { ?holding wm:heldByInvestor ?investor . }

      OPTIONAL { ?action wm:rebalancingActionOfInvestor ?investor . }

      OPTIONAL {
        ?health wm:healthOfInvestor ?investor .
        ?health wm:riskScore ?riskScoreVal .
      }
    }
    GROUP BY ?investor ?segmentLabel
  }
}
GROUP BY ?segmentLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?categoryName 
       (AVG(xsd:decimal(?holdingsCount)) AS ?avgHoldingsPerInvestor) 
       (AVG(xsd:decimal(?rebalanceCount)) AS ?avgRebalancesPerInvestor) 
       (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore)
WHERE {
  {
    SELECT ?investor ?categoryName 
           (COUNT(DISTINCT ?holding) AS ?holdingsCount) 
           (COUNT(DISTINCT ?rebalance) AS ?rebalanceCount) 
           (AVG(xsd:decimal(?riskScoreVal)) AS ?riskScore)
    WHERE {
      ?investor rdf:type wm:Investor .

      OPTIONAL {
        ?investor wm:hasCategory ?cat .
        OPTIONAL { ?cat rdfs:label ?categoryName }
      }

      OPTIONAL { ?holding wm:heldByInvestor ?investor . }

      OPTIONAL { ?rebalance wm:rebalancingActionOfInvestor ?investor . }

      OPTIONAL {
        ?ph wm:healthOfInvestor ?investor ;
            wm:riskScore ?riskScoreVal .
      }
    }
    GROUP BY ?investor ?categoryName
  }
}
GROUP BY ?categoryName

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category
       (AVG(xsd:decimal(?holdingsCount)) AS ?avgHoldingsPerInvestor)
       (AVG(xsd:decimal(?cashFlowSum)) AS ?avgNetCashFlowPerInvestor)
       (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore)
WHERE {
  {
    SELECT ?investor ?category (COUNT(?holding) AS ?holdingsCount) (SUM(xsd:decimal(?amt)) AS ?cashFlowSum) ?riskScore
    WHERE {
      ?investor rdf:type wm:Investor .
      OPTIONAL { ?investor wm:category ?category . }
      OPTIONAL {
        ?investor wm:hasHolding ?holding .
        ?holding rdf:type wm:PortfolioHolding .
      }
      OPTIONAL {
        ?cf rdf:type wm:CashFlow .
        ?cf wm:cashFlowOfInvestor ?investor .
        ?cf wm:amount ?amt .
      }
      OPTIONAL {
        ?ph rdf:type wm:PortfolioHealth .
        ?ph wm:healthOfInvestor ?investor .
        ?ph wm:riskScore ?riskScore .
      }
    }
    GROUP BY ?investor ?category ?riskScore
  }
}
GROUP BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category
       (AVG(?totalCashFlow) AS ?avgNetCashFlow)
       (AVG(?avgGoalProgress) AS ?avgGoalProgress)
       (AVG(?riskScore) AS ?avgRiskScore)
WHERE {
  ?inv rdf:type wm:Investor .
  OPTIONAL { ?inv wm:category ?category . }
  ?inv wm:investorId ?investorId .

  # Cash‑flow sum per investor
  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?totalCashFlow)
    WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:amount ?amount .
      ?cf wm:cashFlowOfInvestor ?invCF .
      ?invCF wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }

  # Average goal progress per investor
  OPTIONAL {
    SELECT ?investorId (AVG(xsd:decimal(?progress)) AS ?avgGoalProgress)
    WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:progressPct ?progress .
      ?goal wm:belongsToInvestor ?invGoal .
      ?invGoal wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }

  # Risk score per investor
  OPTIONAL {
    SELECT ?investorId (xsd:decimal(?riskScoreLit) AS ?riskScore)
    WHERE {
      ?ph rdf:type wm:PortfolioHealth .
      ?ph wm:riskScore ?riskScoreLit .
      ?ph wm:healthOfInvestor ?invPH .
      ?invPH wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance ?avgShift ?avgScenarioCount WHERE {
  {
    SELECT ?riskTolerance (AVG(xsd:decimal(?shift)) AS ?avgShift) WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:riskTolerance ?riskTolerance .
      ?scenario rdf:type wm:ScenarioRebalancing .
      ?scenario wm:scenarioRebalancingOfInvestor ?investor .
      ?scenario wm:newAllocationPct ?newAlloc .
      ?scenario wm:currentAllocationPct ?currAlloc .
      BIND(xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc) AS ?shift)
    }
    GROUP BY ?riskTolerance
  }
  {
    SELECT ?riskTolerance (AVG(xsd:decimal(?scenarioCount)) AS ?avgScenarioCount) WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:riskTolerance ?riskTolerance .
      OPTIONAL {
        ?scenario rdf:type wm:ScenarioRebalancing .
        ?scenario wm:scenarioRebalancingOfInvestor ?investor .
      }
      BIND(COUNT(?scenario) AS ?scenarioCount)
    }
    GROUP BY ?riskTolerance
  }
}
ORDER BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance ?avgTotalHoldingValue ?avgHoldingReturn ?avgHoldingGain ?avgDividends
WHERE {
  {
    SELECT ?riskTolerance (AVG(xsd:decimal(?totalHoldingValue)) AS ?avgTotalHoldingValue)
    WHERE {
      ?investor rdf:type wm:Investor .
      OPTIONAL { ?investor wm:riskTolerance ?riskTolerance . }
      {
        SELECT ?investor (SUM(xsd:decimal(?currVal)) AS ?totalHoldingValue)
        WHERE {
          ?holding rdf:type wm:PortfolioHolding .
          ?holding wm:heldByInvestor ?investor .
          ?holding wm:currentValue ?currVal .
        }
        GROUP BY ?investor
      }
    }
    GROUP BY ?riskTolerance
  }
  {
    SELECT ?riskTolerance (AVG(xsd:decimal(?returnsPct)) AS ?avgHoldingReturn) (AVG(xsd:decimal(?gain)) AS ?avgHoldingGain) (AVG(xsd:decimal(?dividendsVal)) AS ?avgDividends)
    WHERE {
      ?investor rdf:type wm:Investor .
      OPTIONAL { ?investor wm:riskTolerance ?riskTolerance . }
      ?holding rdf:type wm:PortfolioHolding .
      ?holding wm:heldByInvestor ?investor .
      ?holding wm:returnsPct ?returnsPct .
      ?holding wm:cost ?cost .
      ?holding wm:currentValue ?currVal .
      FILTER (BOUND(?cost) && BOUND(?currVal))
      BIND ((xsd:decimal(?currVal) - xsd:decimal(?cost)) AS ?gain) .
      OPTIONAL {
        ?holding wm:dividends ?dividends .
        BIND (xsd:decimal(?dividends) AS ?dividendsVal)
      }
    }
    GROUP BY ?riskTolerance
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon ?avgNetCashFlow ?avgCashFlowCount ?avgSignedCashFlowAmount
WHERE {
  {
    SELECT ?timeHorizon (AVG(xsd:decimal(?netSum)) AS ?avgNetCashFlow) (AVG(xsd:decimal(?cfCount)) AS ?avgCashFlowCount)
    WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:timeHorizon ?timeHorizon .
      {
        SELECT ?investor (SUM(xsd:decimal(?amt)) AS ?netSum) (COUNT(?cf) AS ?cfCount)
        WHERE {
          ?cf rdf:type wm:CashFlow .
          ?cf wm:cashFlowOfInvestor ?investor .
          ?cf wm:amount ?amt .
        } GROUP BY ?investor
      }
    } GROUP BY ?timeHorizon
  }
  {
    SELECT ?timeHorizon (AVG(xsd:decimal(?amt)) AS ?avgSignedCashFlowAmount)
    WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:timeHorizon ?timeHorizon .
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?investor .
      ?cf wm:amount ?amt .
    } GROUP BY ?timeHorizon
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?totalHoldingValue WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?holdingValue)) AS ?totalHoldingValue) WHERE {
      ?holding rdf:type wm:PortfolioHolding .
      ?holding wm:investorId ?investorId .
      ?holding wm:currentValue ?holdingValue .
    }
    GROUP BY ?investorId
  }
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:investorName ?investorName . }
}
ORDER BY DESC(?totalHoldingValue)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon 
       (AVG(?avgAmount) AS ?avgRebalanceAmount) 
       (AVG(?avgShift) AS ?avgRebalanceShift) 
       (AVG(?rebalanceCount) AS ?avgRebalanceCount)
WHERE {
  {
    SELECT ?investor ?timeHorizon 
           (IF(?actionCount > 0, ?sumAmount / xsd:decimal(?actionCount), 0) AS ?avgAmount)
           (IF(?actionCount > 0, ?sumShift / xsd:decimal(?actionCount), 0) AS ?avgShift)
           (xsd:decimal(?rebalanceCount) AS ?rebalanceCount)
    WHERE {
      ?investor rdf:type wm:Investor .
      OPTIONAL { ?investor wm:timeHorizon ?timeHorizon . }

      OPTIONAL {
        ?ra rdf:type wm:RebalancingAction .
        ?ra wm:rebalancingActionOfInvestor ?investor .
        OPTIONAL { ?ra wm:amount ?raAmount . }
        OPTIONAL { ?ra wm:currentAllocationPct ?currAlloc . }
        OPTIONAL { ?ra wm:targetAllocationPct ?tgtAlloc . }

        BIND(IF(BOUND(?raAmount), xsd:decimal(?raAmount), 0) AS ?raAmountDec)
        BIND(IF(BOUND(?tgtAlloc) && BOUND(?currAlloc),
                xsd:decimal(?tgtAlloc) - xsd:decimal(?currAlloc),
                0) AS ?shift)
      }

      BIND(COUNT(?ra) AS ?rebalanceCount)
      BIND(SUM(?raAmountDec) AS ?sumAmount)
      BIND(SUM(?shift) AS ?sumShift)
      BIND(COUNT(?ra) AS ?actionCount)
    }
    GROUP BY ?investor ?timeHorizon
  }
}
GROUP BY ?timeHorizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon
       (AVG(xsd:decimal(?progressPct)) AS ?avgGoalProgress)
       (AVG(xsd:decimal(?shortfall)) AS ?avgGoalShortfall)
       (AVG(xsd:decimal(?avgAnnualReturnPct)) AS ?avgAnnualReturn)
       (AVG(xsd:decimal(?avgVolatilityPct)) AS ?avgGoalVolatility)
WHERE {
  ?investor rdf:type wm:Investor .
  OPTIONAL { ?investor wm:timeHorizon ?timeHorizon . }
  ?goal rdf:type wm:InvestmentGoal .
  ?goal wm:belongsToInvestor ?investor .
  OPTIONAL { ?goal wm:progressPct ?progressPct . }
  OPTIONAL { ?goal wm:shortfall ?shortfall . }
  OPTIONAL { ?goal wm:avgAnnualReturnPct ?avgAnnualReturnPct . }
  OPTIONAL { ?goal wm:avgVolatilityPct ?avgVolatilityPct . }
}
GROUP BY ?timeHorizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segmentLabel ?avgNetCashFlow ?avgSignedAmount ?avgCashFlowCount
WHERE {
  # Segment label
  ?segment rdf:type wm:Segment .
  OPTIONAL { ?segment rdfs:label ?segmentLabel . }

  # Average net cash flow and average cash‑flow count per investor, then averaged by segment
  {
    SELECT ?segment (AVG(xsd:decimal(?totalAmount)) AS ?avgNetCashFlow) (AVG(xsd:decimal(?flowCount)) AS ?avgCashFlowCount)
    WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:hasSegment ?segment .
      {
        SELECT ?investor (SUM(xsd:decimal(?amt)) AS ?totalAmount) (COUNT(?cf) AS ?flowCount)
        WHERE {
          ?cf rdf:type wm:CashFlow .
          ?cf wm:cashFlowOfInvestor ?investor .
          ?cf wm:amount ?amt .
        }
        GROUP BY ?investor
      }
    }
    GROUP BY ?segment
  }

  # Average signed cash‑flow amount per segment
  {
    SELECT ?segment (AVG(xsd:decimal(?amtSigned)) AS ?avgSignedAmount)
    WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:hasSegment ?segment .
      ?cfSigned rdf:type wm:CashFlow .
      ?cfSigned wm:cashFlowOfInvestor ?investor .
      ?cfSigned wm:amount ?amtSigned .
    }
    GROUP BY ?segment
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon 
       (AVG(?shift) AS ?avgScenarioShift) 
       (AVG(xsd:decimal(?invScenarioCount)) AS ?avgScenarioCount)
WHERE {
  ?investor rdf:type wm:Investor .
  OPTIONAL {
    ?investor wm:hasScenarioRebalancing ?scenario .
    ?scenario wm:newAllocationPct ?newAlloc .
    ?scenario wm:currentAllocationPct ?currAlloc .
    BIND (xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc) AS ?shift)
  }
  {
    SELECT ?investor (COUNT(?sc) AS ?invScenarioCount)
    WHERE {
      ?investor rdf:type wm:Investor .
      OPTIONAL { ?investor wm:hasScenarioRebalancing ?sc . }
    } GROUP BY ?investor
  }
  OPTIONAL { ?investor wm:timeHorizon ?timeHorizon . }
}
GROUP BY ?timeHorizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon (AVG(xsd:decimal(?investorTotalHoldingValue)) AS ?avgTotalHoldingValue) ?avgHoldingReturn ?avgHoldingGain ?avgDividends
WHERE {
  {
    SELECT ?investorId ?timeHorizon (SUM(xsd:decimal(?currentValue)) AS ?investorTotalHoldingValue)
    WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:investorId ?investorId .
      OPTIONAL { ?investor wm:timeHorizon ?timeHorizon . }
      ?holding rdf:type wm:PortfolioHolding .
      ?holding wm:heldByInvestor ?investor .
      ?holding wm:currentValue ?currentValue .
    }
    GROUP BY ?investorId ?timeHorizon
  }
  {
    SELECT ?timeHorizon (AVG(xsd:decimal(?returnsPct)) AS ?avgHoldingReturn) (AVG(xsd:decimal(?gain)) AS ?avgHoldingGain) (AVG(xsd:decimal(?dividends)) AS ?avgDividends)
    WHERE {
      ?investor rdf:type wm:Investor .
      OPTIONAL { ?investor wm:timeHorizon ?timeHorizon . }
      ?holding rdf:type wm:PortfolioHolding .
      ?holding wm:heldByInvestor ?investor .
      OPTIONAL { ?holding wm:returnsPct ?returnsPct . }
      OPTIONAL {
        ?holding wm:cost ?cost .
        ?holding wm:currentValue ?curr .
        BIND((xsd:decimal(?curr) - xsd:decimal(?cost)) AS ?gain)
      }
      OPTIONAL { ?holding wm:dividends ?dividends . }
      FILTER(BOUND(?returnsPct) && BOUND(?gain) && BOUND(?dividends))
    }
    GROUP BY ?timeHorizon
  }
}
GROUP BY ?timeHorizon ?avgHoldingReturn ?avgHoldingGain ?avgDividends

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTol
       (AVG(xsd:decimal(?netCashFlow)) AS ?avgNetCashFlow)
       (AVG(xsd:decimal(?signedCashFlowAmt)) AS ?avgSignedCashFlowAmount)
       (AVG(xsd:decimal(?totalHoldingValue)) AS ?avgTotalHoldingValue)
WHERE {
  ?investor rdf:type wm:Investor .
  OPTIONAL { ?investor wm:riskTolerance ?riskTol . }

  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?cfAmt1)) AS ?netCashFlow)
    WHERE {
      ?cf1 rdf:type wm:CashFlow .
      ?cf1 wm:cashFlowOfInvestor ?investor .
      ?cf1 wm:amount ?cfAmt1 .
    }
    GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (AVG(xsd:decimal(?cfAmt2)) AS ?signedCashFlowAmt)
    WHERE {
      ?cf2 rdf:type wm:CashFlow .
      ?cf2 wm:cashFlowOfInvestor ?investor .
      ?cf2 wm:amount ?cfAmt2 .
    }
    GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?holdVal)) AS ?totalHoldingValue)
    WHERE {
      ?hold rdf:type wm:PortfolioHolding .
      ?hold wm:heldByInvestor ?investor .
      ?hold wm:currentValue ?holdVal .
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTol

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (AVG(xsd:decimal(?netCashFlow)) AS ?avgNetCashFlow)
       (AVG(xsd:decimal(?cfAmount)) AS ?avgSignedCashFlow)
       (AVG(xsd:decimal(?scenarioShift)) AS ?avgScenarioShift)
WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .
  ?investor wm:hasRiskTolerance ?rt .
  ?rt wm:riskTolerance ?riskTolerance .

  # Net cash flow per investor
  OPTIONAL {
    {
      SELECT ?investorId (SUM(xsd:decimal(?cfAmt)) AS ?netCashFlow)
      WHERE {
        ?cf rdf:type wm:CashFlow .
        ?cf wm:hasCashFlowOfInvestor ?inv .
        ?inv wm:investorId ?investorId .
        ?cf wm:amount ?cfAmt .
      }
      GROUP BY ?investorId
    }
  }

  # Individual cash‑flow amounts for signed average
  OPTIONAL {
    ?cfInd rdf:type wm:CashFlow .
    ?cfInd wm:hasCashFlowOfInvestor ?investor .
    ?cfInd wm:amount ?cfAmount .
  }

  # Scenario shift per investor
  OPTIONAL {
    {
      SELECT ?investorId (AVG(xsd:decimal(?newPct) - xsd:decimal(?curPct)) AS ?scenarioShift)
      WHERE {
        ?sr rdf:type wm:ScenarioRebalancing .
        ?sr wm:scenarioRebalancingOfInvestor ?inv2 .
        ?inv2 wm:investorId ?investorId .
        ?sr wm:newAllocationPct ?newPct .
        ?sr wm:currentAllocationPct ?curPct .
      }
      GROUP BY ?investorId
    }
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance (AVG(xsd:decimal(?netCashFlow)) AS ?avgNetCashFlow) (AVG(xsd:decimal(?amount)) AS ?avgSignedCashFlowAmount) (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore)
WHERE {
  # cash flow amount for signed average
  ?cf rdf:type wm:CashFlow .
  ?cf wm:amount ?amount .
  ?cf wm:cashFlowOfInvestor ?investor .

  # investor attributes, net cash flow and risk score
  {
    SELECT ?investor ?riskTolerance ?netCashFlow ?riskScore WHERE {
      ?investor rdf:type wm:Investor .
      OPTIONAL { ?investor wm:riskTolerance ?riskTolerance . }

      # net cash flow per investor
      {
        SELECT ?investor (SUM(xsd:decimal(?amt)) AS ?netCashFlow) WHERE {
          ?cflow rdf:type wm:CashFlow .
          ?cflow wm:amount ?amt .
          ?cflow wm:cashFlowOfInvestor ?investor .
        } GROUP BY ?investor
      }

      OPTIONAL {
        ?ph rdf:type wm:PortfolioHealth .
        ?ph wm:healthOfInvestor ?investor .
        ?ph wm:riskScore ?riskScore .
      }
    }
  }

  BIND(COALESCE(?riskTolerance, "NULL") AS ?riskTolerance)
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskLabel
       (AVG(?netCashFlow) AS ?avgNetCashFlow)
       (AVG(?signedAvg) AS ?avgSignedCashFlow)
       (AVG(?goalProgress) AS ?avgGoalProgress)
WHERE {
  ?investor rdf:type wm:Investor .
  OPTIONAL { ?investor wm:hasRiskTolerance ?rt . ?rt rdfs:label ?riskLabel . }
  BIND (COALESCE(?riskLabel, "NULL") AS ?riskLabel) .

  {
    SELECT ?investor (SUM(xsd:decimal(?cfAmt)) AS ?netCashFlow)
    WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:hasCashFlowOfInvestor ?investor .
      ?cf wm:amount ?cfAmt .
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (AVG(xsd:decimal(?cfAmt2)) AS ?signedAvg)
    WHERE {
      ?cf2 rdf:type wm:CashFlow .
      ?cf2 wm:hasCashFlowOfInvestor ?investor .
      ?cf2 wm:amount ?cfAmt2 .
    }
    GROUP BY ?investor
  }

  OPTIONAL {
    ?goal rdf:type wm:InvestmentGoal .
    ?goal wm:belongsToInvestor ?investor .
    ?goal wm:progressPct ?gp .
    BIND (xsd:decimal(?gp) AS ?goalProgress)
  }
}
GROUP BY ?riskLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance ?avgTotalInvestment ?avgAllocationPct ?avgScenarioShift WHERE {
  {
    SELECT ?riskTolerance (AVG(xsd:decimal(?totalInvestment)) AS ?avgTotalInvestment) (AVG(xsd:decimal(?allocationPct)) AS ?avgAllocationPct) WHERE {
      ?inv rdf:type wm:Investor .
      ?inv wm:investorId ?invId .
      OPTIONAL { ?inv wm:riskTolerance ?riskTolerance . }
      ?sa rdf:type wm:SectorAllocation .
      ?sa wm:investorId ?invId .
      ?sa wm:totalInvestment ?totalInvestment .
      ?sa wm:allocationPct ?allocationPct .
    } GROUP BY ?riskTolerance
  }
  OPTIONAL {
    SELECT ?riskTolerance (AVG(xsd:decimal(?shift)) AS ?avgScenarioShift) WHERE {
      ?inv rdf:type wm:Investor .
      ?inv wm:investorId ?invId .
      OPTIONAL { ?inv wm:riskTolerance ?riskTolerance . }
      ?sr rdf:type wm:ScenarioRebalancing .
      ?sr wm:investorId ?invId .
      ?sr wm:newAllocationPct ?newAlloc .
      ?sr wm:currentAllocationPct ?currAlloc .
      BIND (xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc) AS ?shift)
    } GROUP BY ?riskTolerance
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance ?avgTotalHoldingValue ?avgHoldingReturn ?avgRiskScore WHERE {
  {
    SELECT ?riskTolerance (AVG(?totalHoldingValue) AS ?avgTotalHoldingValue) WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:investorId ?investorId .
      ?investor wm:riskTolerance ?riskTolerance .
      {
        SELECT ?investorId (SUM(xsd:decimal(?currVal)) AS ?totalHoldingValue) WHERE {
          ?holding rdf:type wm:PortfolioHolding .
          ?holding wm:investorId ?investorId .
          ?holding wm:currentValue ?currVal .
        } GROUP BY ?investorId
      }
    } GROUP BY ?riskTolerance
  }
  {
    SELECT ?riskTolerance (AVG(?holdingReturn) AS ?avgHoldingReturn) WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:investorId ?investorId .
      ?investor wm:riskTolerance ?riskTolerance .
      {
        SELECT ?investorId ((xsd:decimal(?currVal) - xsd:decimal(?cost)) / xsd:decimal(?cost) AS ?holdingReturn) WHERE {
          ?h rdf:type wm:PortfolioHolding .
          ?h wm:investorId ?investorId .
          ?h wm:currentValue ?currVal .
          ?h wm:cost ?cost .
        }
      }
    } GROUP BY ?riskTolerance
  }
  {
    SELECT ?riskTolerance (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore) WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:investorId ?investorId .
      ?investor wm:riskTolerance ?riskTolerance .
      ?ph rdf:type wm:PortfolioHealth .
      ?ph wm:investorId ?investorId .
      ?ph wm:riskScore ?riskScore .
    } GROUP BY ?riskTolerance
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance ?avgTotalHoldingValue ?avgHoldingReturn ?avgGoalProgress WHERE {
  {
    SELECT ?riskTolerance (AVG(?totalHoldingValue) AS ?avgTotalHoldingValue) WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:investorId ?investorId .
      ?investor wm:riskTolerance ?riskTolerance .
      {
        SELECT ?investorId (SUM(xsd:decimal(?currVal)) AS ?totalHoldingValue) WHERE {
          ?holding rdf:type wm:PortfolioHolding .
          ?holding wm:heldByInvestor ?investor .
          ?holding wm:currentValue ?currVal .
        } GROUP BY ?investorId
      }
    } GROUP BY ?riskTolerance
  }
  {
    SELECT ?riskTolerance (AVG(?holdingReturn) AS ?avgHoldingReturn) WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:investorId ?investorId .
      ?investor wm:riskTolerance ?riskTolerance .
      ?holding rdf:type wm:PortfolioHolding .
      ?holding wm:heldByInvestor ?investor .
      ?holding wm:cost ?cost .
      ?holding wm:currentValue ?currVal .
      BIND( (xsd:decimal(?currVal) - xsd:decimal(?cost)) / xsd:decimal(?cost) AS ?holdingReturn )
      FILTER(xsd:decimal(?cost) != 0)
    } GROUP BY ?riskTolerance
  }
  {
    SELECT ?riskTolerance (AVG(xsd:decimal(?progressPct)) AS ?avgGoalProgress) WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:investorId ?investorId .
      ?investor wm:riskTolerance ?riskTolerance .
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?investor .
      ?goal wm:progressPct ?progressPct .
    } GROUP BY ?riskTolerance
  }
}
ORDER BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon
       (AVG(xsd:decimal(?netCashFlow)) AS ?avgNetCashFlow)
       (AVG(xsd:decimal(?totalHoldingValue)) AS ?avgTotalHoldingValue)
       ?avgSignedCashFlowAmount
WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:hasTimeHorizon ?timeHorizon .

  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?cfAmt)) AS ?netCashFlow)
    WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?investor .
      ?cf wm:amount ?cfAmt .
    }
    GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?holdVal)) AS ?totalHoldingValue)
    WHERE {
      ?hold rdf:type wm:PortfolioHolding .
      ?hold wm:heldByInvestor ?investor .
      ?hold wm:currentValue ?holdVal .
    }
    GROUP BY ?investor
  }

  {
    SELECT ?timeHorizon (AVG(xsd:decimal(?cfAmtSigned)) AS ?avgSignedCashFlowAmount)
    WHERE {
      ?inv rdf:type wm:Investor .
      ?inv wm:hasTimeHorizon ?timeHorizon .
      ?cfSigned rdf:type wm:CashFlow .
      ?cfSigned wm:cashFlowOfInvestor ?inv .
      ?cfSigned wm:amount ?cfAmtSigned .
    }
    GROUP BY ?timeHorizon
  }
}
GROUP BY ?timeHorizon ?avgSignedCashFlowAmount

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTol
       (AVG(xsd:decimal(?shift)) AS ?avgScenarioShift)
       (AVG(xsd:decimal(?scenarioCount)) AS ?avgScenarioCount)
       (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore)
WHERE {
  ?investor rdf:type wm:Investor .
  OPTIONAL { ?investor wm:riskTolerance ?riskTol . }

  # Scenario shift values
  OPTIONAL {
    ?investor wm:hasScenarioRebalancing ?sr .
    ?sr rdf:type wm:ScenarioRebalancing .
    ?sr wm:newAllocationPct ?newAlloc .
    ?sr wm:currentAllocationPct ?curAlloc .
    BIND (xsd:decimal(?newAlloc) - xsd:decimal(?curAlloc) AS ?shift)
  }

  # Scenario count per investor (including zero)
  {
    SELECT ?investor (COUNT(?sr2) AS ?scenarioCount)
    WHERE {
      ?investor rdf:type wm:Investor .
      OPTIONAL {
        ?investor wm:hasScenarioRebalancing ?sr2 .
        ?sr2 rdf:type wm:ScenarioRebalancing .
      }
    } GROUP BY ?investor
  }

  # Risk score from PortfolioHealth
  OPTIONAL {
    ?ph rdf:type wm:PortfolioHealth .
    ?ph wm:healthOfInvestor ?investor .
    ?ph wm:riskScore ?riskScore .
  }
}
GROUP BY ?riskTol

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?compositeScore WHERE {
  ?inv rdf:type wm:Investor .
  ?inv wm:investorId ?investorId .

  {
    SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlow) WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:investorId ?investorId .
      ?cf wm:amount ?cfAmount .
    } GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?saAmount)) AS ?totalSectorInvestment) WHERE {
      ?sa rdf:type wm:SectorAllocation .
      ?sa wm:investorId ?investorId .
      ?sa wm:totalInvestment ?saAmount .
    } GROUP BY ?investorId
  }

  BIND ((xsd:decimal(?netCashFlow) + xsd:decimal(?totalSectorInvestment)) AS ?compositeScore)
}
ORDER BY DESC(?compositeScore) ASC(?investorId)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskToleranceLabel ?avgTotalInvestment ?avgAllocationPct ?avgGoalProgress
WHERE {
  {
    SELECT ?riskToleranceLabel (AVG(xsd:decimal(?totalInv)) AS ?avgTotalInvestment) (AVG(xsd:decimal(?allocPct)) AS ?avgAllocationPct)
    WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:hasRiskTolerance ?rt .
      ?rt rdfs:label ?riskToleranceLabel .
      ?investor wm:hasSectorAllocation ?sa .
      ?sa wm:totalInvestment ?totalInv .
      ?sa wm:allocationPct ?allocPct .
    }
    GROUP BY ?riskToleranceLabel
  }
  {
    SELECT ?riskToleranceLabel (AVG(xsd:decimal(?progPct)) AS ?avgGoalProgress)
    WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:hasRiskTolerance ?rt .
      ?rt rdfs:label ?riskToleranceLabel .
      ?investor wm:hasInvestmentGoal ?ig .
      ?ig wm:progressPct ?progPct .
    }
    GROUP BY ?riskToleranceLabel
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance ?avgNetCashFlow ?avgSignedCashFlowAmt ?avgRebalanceAmt WHERE {
  {
    SELECT ?riskTolerance (AVG(xsd:decimal(?netCashFlow)) AS ?avgNetCashFlow) WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:hasRiskTolerance ?rt .
      ?rt rdfs:label ?riskTolerance .
      OPTIONAL {
        SELECT ?investor (SUM(xsd:decimal(?cfAmt)) AS ?netCashFlow) WHERE {
          ?investor wm:hasCashFlow ?cf .
          ?cf wm:amount ?cfAmt .
        } GROUP BY ?investor
      }
    } GROUP BY ?riskTolerance
  }
  {
    SELECT ?riskTolerance (AVG(xsd:decimal(?cfAmt)) AS ?avgSignedCashFlowAmt) WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:hasRiskTolerance ?rt .
      ?rt rdfs:label ?riskTolerance .
      ?investor wm:hasCashFlow ?cf .
      ?cf wm:amount ?cfAmt .
    } GROUP BY ?riskTolerance
  }
  {
    SELECT ?riskTolerance (AVG(xsd:decimal(?rebalanceAmt)) AS ?avgRebalanceAmt) WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:hasRiskTolerance ?rt .
      ?rt rdfs:label ?riskTolerance .
      OPTIONAL {
        SELECT ?investor (SUM(xsd:decimal(?raAmt)) AS ?rebalanceAmt) WHERE {
          ?investor wm:hasRebalancingAction ?ra .
          ?ra wm:amount ?raAmt .
        } GROUP BY ?investor
      }
    } GROUP BY ?riskTolerance
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?compositeScore WHERE {
  # per‑investor cash flow and scenario shift
  {
    SELECT ?investorId ?netCashFlow ?totalShift WHERE {
      {
        SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?netCashFlow) WHERE {
          ?cf rdf:type wm:CashFlow .
          ?cf wm:investorId ?investorId .
          ?cf wm:amount ?amount .
        } GROUP BY ?investorId
      }
      {
        SELECT ?investorId (SUM(xsd:decimal(?shift)) AS ?totalShift) WHERE {
          ?sr rdf:type wm:ScenarioRebalancing .
          ?sr wm:investorId ?investorId .
          ?sr wm:newAllocationPct ?new .
          ?sr wm:currentAllocationPct ?cur .
          BIND( (xsd:decimal(?new) - xsd:decimal(?cur)) AS ?shift )
        } GROUP BY ?investorId
      }
    }
  }
  # global minima and maxima for normalization
  {
    SELECT (MIN(?nc) AS ?minCash) (MAX(?nc) AS ?maxCash) (MIN(?ts) AS ?minShift) (MAX(?ts) AS ?maxShift) WHERE {
      {
        SELECT ?investorId ?nc ?ts WHERE {
          {
            SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?nc) WHERE {
              ?cf rdf:type wm:CashFlow .
              ?cf wm:investorId ?investorId .
              ?cf wm:amount ?amount .
            } GROUP BY ?investorId
          }
          {
            SELECT ?investorId (SUM(xsd:decimal(?shift)) AS ?ts) WHERE {
              ?sr rdf:type wm:ScenarioRebalancing .
              ?sr wm:investorId ?investorId .
              ?sr wm:newAllocationPct ?new .
              ?sr wm:currentAllocationPct ?cur .
              BIND( (xsd:decimal(?new) - xsd:decimal(?cur)) AS ?shift )
            } GROUP BY ?investorId
          }
        }
      }
    }
  }
  # normalization and composite score
  BIND( IF(?maxCash != ?minCash, (xsd:decimal(?netCashFlow) - ?minCash) / (?maxCash - ?minCash), 0) AS ?normCash )
  BIND( IF(?maxShift != ?minShift, (xsd:decimal(?totalShift) - ?minShift) / (?maxShift - ?minShift), 0) AS ?normShift )
  BIND( ((?normCash + ?normShift) / 2) * 100 AS ?compositeScore )
}
ORDER BY DESC(?compositeScore) ASC(?investorId)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskToleranceLabel
       (AVG(xsd:decimal(?shift)) AS ?avgScenarioShift)
       (AVG(xsd:decimal(?scenarioCount)) AS ?avgScenarioCount)
       (AVG(xsd:decimal(?goalProgress)) AS ?avgGoalProgress)
WHERE {
  # Investor and risk tolerance
  ?investor rdf:type wm:Investor .
  OPTIONAL {
    ?investor wm:hasRiskTolerance ?rt .
    OPTIONAL { ?rt rdfs:label ?riskToleranceLabel . }
  }
  BIND (COALESCE(?riskToleranceLabel, "NULL") AS ?riskToleranceLabel)

  # Scenario count per investor
  {
    SELECT ?investor (COUNT(?sr) AS ?scenarioCount)
    WHERE {
      ?investor rdf:type wm:Investor .
      OPTIONAL {
        ?investor wm:hasScenarioRebalancing ?sr .
        ?sr rdf:type wm:ScenarioRebalancing .
      }
    }
    GROUP BY ?investor
  }

  # Scenario shift per scenario (new - current)
  OPTIONAL {
    ?investor wm:hasScenarioRebalancing ?sr2 .
    ?sr2 rdf:type wm:ScenarioRebalancing .
    ?sr2 wm:newAllocationPct ?newAlloc .
    ?sr2 wm:currentAllocationPct ?curAlloc .
    BIND ((xsd:decimal(?newAlloc) - xsd:decimal(?curAlloc)) AS ?shift)
  }

  # Goal progress per investor
  OPTIONAL {
    ?investor wm:hasInvestmentGoal ?goal .
    ?goal rdf:type wm:InvestmentGoal .
    ?goal wm:progressPct ?goalProgress .
  }
}
GROUP BY ?riskToleranceLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?compositeScore WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?totalCashFlow) WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:amount ?amount .
      ?cf wm:investorId ?investorId .
    } GROUP BY ?investorId
  }
  {
    SELECT ?investorId (MAX(xsd:decimal(?riskScore)) AS ?riskScore) WHERE {
      ?ph rdf:type wm:PortfolioHealth .
      ?ph wm:riskScore ?riskScore .
      ?ph wm:investorId ?investorId .
    } GROUP BY ?investorId
  }
  {
    SELECT (MIN(?totalCashFlow) AS ?minCash) (MAX(?totalCashFlow) AS ?maxCash)
           (MIN(?riskScore) AS ?minRisk) (MAX(?riskScore) AS ?maxRisk) WHERE {
      {
        SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?totalCashFlow) WHERE {
          ?cf rdf:type wm:CashFlow .
          ?cf wm:amount ?amount .
          ?cf wm:investorId ?investorId .
        } GROUP BY ?investorId
      }
      {
        SELECT ?investorId (MAX(xsd:decimal(?riskScore)) AS ?riskScore) WHERE {
          ?ph rdf:type wm:PortfolioHealth .
          ?ph wm:riskScore ?riskScore .
          ?ph wm:investorId ?investorId .
        } GROUP BY ?investorId
      }
    }
  }
  BIND( (xsd:decimal(?totalCashFlow) - xsd:decimal(?minCash)) / (xsd:decimal(?maxCash) - xsd:decimal(?minCash)) AS ?normCash )
  BIND( (xsd:decimal(?riskScore) - xsd:decimal(?minRisk)) / (xsd:decimal(?maxRisk) - xsd:decimal(?minRisk)) AS ?normRisk )
  BIND( 100 * ((?normCash + ?normRisk) / 2) AS ?compositeScore )
}
ORDER BY DESC(?compositeScore) ASC(?investorId)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?netCashFlow ?avgShortfall ?compositeScore
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
    WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:investorId ?investorId .
      ?cf wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?shortfall)) AS ?avgShortfall)
    WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:investorId ?investorId .
      ?goal wm:shortfall ?shortfall .
    }
    GROUP BY ?investorId
  }
  ?inv rdf:type wm:Investor .
  ?inv wm:investorId ?investorId .
  BIND((?netCashFlow - ?avgShortfall) AS ?compositeScore)
}
ORDER BY DESC(?compositeScore) ASC(?investorId)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?totalRebalance ?totalSectorInv ?compositeScore
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?rebAmt)) AS ?totalRebalance)
    WHERE {
      ?ra rdf:type wm:RebalancingAction .
      ?ra wm:investorId ?investorId .
      ?ra wm:amount ?rebAmt .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?secInv)) AS ?totalSectorInv)
    WHERE {
      ?sa rdf:type wm:SectorAllocation .
      ?sa wm:investorId ?investorId .
      ?sa wm:totalInvestment ?secInv .
    }
    GROUP BY ?investorId
  }
  BIND ((xsd:decimal(?totalRebalance) + xsd:decimal(?totalSectorInv)) AS ?compositeScore)
}
ORDER BY DESC(?compositeScore) ASC(?investorId)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?compositeScore WHERE {
  {
    SELECT ?investorId ?totalGain ?riskScore WHERE {
      {
        SELECT ?investorId (SUM(xsd:decimal(?gain)) AS ?totalGain) WHERE {
          ?investor rdf:type wm:Investor .
          ?investor wm:investorId ?investorId .
          ?investor wm:hasHolding ?holding .
          ?holding rdf:type wm:PortfolioHolding .
          ?holding wm:cost ?cost .
          ?holding wm:currentValue ?curr .
          BIND((xsd:decimal(?curr) - xsd:decimal(?cost)) AS ?gain)
        } GROUP BY ?investorId
      }
      {
        SELECT ?investorId (MAX(xsd:decimal(?riskScore)) AS ?riskScore) WHERE {
          ?ph rdf:type wm:PortfolioHealth .
          ?ph wm:investorId ?investorId .
          ?ph wm:riskScore ?riskScore .
        } GROUP BY ?investorId
      }
    }
  }
  {
    SELECT (MIN(?tg) AS ?minGain) (MAX(?tg) AS ?maxGain) (MIN(?rs) AS ?minRisk) (MAX(?rs) AS ?maxRisk) WHERE {
      {
        SELECT ?investorId (SUM(xsd:decimal(?gain)) AS ?tg) WHERE {
          ?investor rdf:type wm:Investor .
          ?investor wm:investorId ?investorId .
          ?investor wm:hasHolding ?holding .
          ?holding rdf:type wm:PortfolioHolding .
          ?holding wm:cost ?cost .
          ?holding wm:currentValue ?curr .
          BIND((xsd:decimal(?curr) - xsd:decimal(?cost)) AS ?gain)
        } GROUP BY ?investorId
      }
      {
        SELECT ?investorId (MAX(xsd:decimal(?riskScore)) AS ?rs) WHERE {
          ?ph rdf:type wm:PortfolioHealth .
          ?ph wm:investorId ?investorId .
          ?ph wm:riskScore ?riskScore .
        } GROUP BY ?investorId
      }
    }
  }
  BIND( IF(?maxGain = ?minGain, 0, (xsd:decimal(?totalGain) - ?minGain) / (?maxGain - ?minGain)) AS ?normGain )
  BIND( IF(?maxRisk = ?minRisk, 0, (xsd:decimal(?riskScore) - ?minRisk) / (?maxRisk - ?minRisk)) AS ?normRisk )
  BIND( ((?normGain + ?normRisk) / 2) * 100 AS ?compositeScore )
}
ORDER BY DESC(?compositeScore) ASC(?investorId)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?totalGain ?avgShortfall ?compositeScore WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .

  {
    SELECT ?investorId (SUM(xsd:decimal(?gain)) AS ?totalGain) WHERE {
      ?holding rdf:type wm:PortfolioHolding .
      ?holding wm:investorId ?investorId .
      ?holding wm:cost ?cost .
      ?holding wm:currentValue ?currentValue .
      BIND(xsd:decimal(?currentValue) - xsd:decimal(?cost) AS ?gain)
      FILTER(bound(?cost) && bound(?currentValue))
    } GROUP BY ?investorId
  }

  {
    SELECT ?investorId (AVG(xsd:decimal(?shortfall)) AS ?avgShortfall) WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:investorId ?investorId .
      ?goal wm:shortfall ?shortfall .
      FILTER(bound(?shortfall))
    } GROUP BY ?investorId
  }

  BIND(?totalGain - ?avgShortfall AS ?compositeScore)
}
ORDER BY DESC(?compositeScore) ASC(?investorId)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (AVG(xsd:decimal(?netCashFlow)) AS ?avgNetCashFlow)
       (AVG(xsd:decimal(?avgSignedCashFlowAmt)) AS ?avgSignedCashFlowAmt)
       (AVG(xsd:decimal(?totalHoldingValue)) AS ?avgTotalHoldingValue)
       (AVG(xsd:decimal(?avgRebalanceAmt)) AS ?avgRebalanceAmt)
WHERE {
  ?investor rdf:type wm:Investor .
  OPTIONAL { ?investor wm:riskTolerance ?riskTolerance . }

  {
    SELECT ?investor (SUM(xsd:decimal(?cfAmt)) AS ?netCashFlow) (AVG(xsd:decimal(?cfAmt)) AS ?avgSignedCashFlowAmt)
    WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?investor .
      ?cf wm:amount ?cfAmt .
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (SUM(xsd:decimal(?holdingVal)) AS ?totalHoldingValue)
    WHERE {
      ?holding rdf:type wm:PortfolioHolding .
      ?holding wm:heldByInvestor ?investor .
      ?holding wm:currentValue ?holdingVal .
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (AVG(xsd:decimal(?rebAmt)) AS ?avgRebalanceAmt)
    WHERE {
      ?reb rdf:type wm:RebalancingAction .
      ?reb wm:rebalancingActionOfInvestor ?investor .
      ?reb wm:amount ?rebAmt .
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskToleranceLabel ?avgSignedCashFlow ?avgNetCashFlow ?avgHoldingValue ?avgSectorInvestment
WHERE {
  {
    SELECT ?rt (AVG(xsd:decimal(?cfAmount)) AS ?avgSignedCashFlow)
    WHERE {
      ?cf rdf:type wm:CashFlow ;
          wm:amount ?cfAmount ;
          wm:cashFlowOfInvestor ?investor .
      ?investor rdf:type wm:Investor ;
                wm:hasRiskTolerance ?rt .
    }
    GROUP BY ?rt
  }
  {
    SELECT ?rt (AVG(xsd:decimal(?totalCashFlow)) AS ?avgNetCashFlow)
           (AVG(xsd:decimal(?totalHoldingValue)) AS ?avgHoldingValue)
           (AVG(xsd:decimal(?totalSectorInvestment)) AS ?avgSectorInvestment)
    WHERE {
      {
        SELECT ?investor ?rt
               (SUM(xsd:decimal(?cfAmt)) AS ?totalCashFlow)
               (SUM(xsd:decimal(?holdVal)) AS ?totalHoldingValue)
               (SUM(xsd:decimal(?secInv)) AS ?totalSectorInvestment)
        WHERE {
          ?investor rdf:type wm:Investor ;
                    wm:hasRiskTolerance ?rt .
          OPTIONAL {
            ?cf2 rdf:type wm:CashFlow ;
                 wm:amount ?cfAmt ;
                 wm:cashFlowOfInvestor ?investor .
          }
          OPTIONAL {
            ?hold rdf:type wm:PortfolioHolding ;
                  wm:currentValue ?holdVal ;
                  wm:heldByInvestor ?investor .
          }
          OPTIONAL {
            ?sec rdf:type wm:SectorAllocation ;
                 wm:totalInvestment ?secInv ;
                 wm:allocationOfInvestor ?investor .
          }
        }
        GROUP BY ?investor ?rt
      }
    }
    GROUP BY ?rt
  }
  OPTIONAL { ?rt rdfs:label ?riskToleranceLabel . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTol 
       (AVG(xsd:decimal(?netCashFlow)) AS ?avgNetCashFlow) 
       (AVG(xsd:decimal(?signedCashFlow)) AS ?avgSignedCashFlow) 
       (AVG(xsd:decimal(?totalHolding)) AS ?avgTotalHolding) 
       (AVG(xsd:decimal(?scenarioShift)) AS ?avgScenarioShift)
WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:riskTolerance ?riskTol .

  {
    SELECT ?investor (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlow) (AVG(xsd:decimal(?cfAmount)) AS ?signedCashFlow)
    WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?investor .
      ?cf wm:amount ?cfAmount .
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (SUM(xsd:decimal(?holdValue)) AS ?totalHolding)
    WHERE {
      ?hold rdf:type wm:PortfolioHolding .
      ?hold wm:heldByInvestor ?investor .
      ?hold wm:currentValue ?holdValue .
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (AVG(xsd:decimal(?newPct) - xsd:decimal(?currPct)) AS ?scenarioShift)
    WHERE {
      ?sr rdf:type wm:ScenarioRebalancing .
      ?sr wm:scenarioRebalancingOfInvestor ?investor .
      ?sr wm:newAllocationPct ?newPct .
      ?sr wm:currentAllocationPct ?currPct .
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTol

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ( ( ?totalGain + ?totalSector ) AS ?compositeScore )
WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .

  {
    SELECT ?investor (SUM(xsd:decimal(?gain)) AS ?totalGain) (COUNT(?h) AS ?cntHoldings) (COUNT(?hFull) AS ?cntFull)
    WHERE {
      ?h rdf:type wm:PortfolioHolding .
      ?h wm:heldByInvestor ?investor .
      OPTIONAL { ?h wm:cost ?cost . }
      OPTIONAL { ?h wm:currentValue ?curr . }
      BIND( IF(BOUND(?cost) && BOUND(?curr), xsd:decimal(?curr) - xsd:decimal(?cost), 0) AS ?gain )
      BIND( IF(BOUND(?cost) && BOUND(?curr), ?h, UNDEF) AS ?hFull )
    }
    GROUP BY ?investor
    HAVING ( ?cntHoldings = ?cntFull && ?cntHoldings > 0 )
  }

  {
    SELECT ?investor (SUM(xsd:decimal(?totalInv)) AS ?totalSector)
    WHERE {
      ?alloc rdf:type wm:SectorAllocation .
      ?alloc wm:allocationOfInvestor ?investor .
      ?alloc wm:totalInvestment ?totalInv .
    }
    GROUP BY ?investor
  }
}
ORDER BY DESC(?compositeScore) ASC(?investorId)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance 
       (AVG(xsd:decimal(?netCashFlowPerInvestor)) AS ?avgNetCashFlow) 
       (AVG(xsd:decimal(?cashFlowAmount)) AS ?avgCashFlowAmount) 
       (AVG(xsd:decimal(?totalHoldingValue)) AS ?avgTotalHoldingValue) 
       (AVG(xsd:decimal(?goalProgress)) AS ?avgGoalProgress)
WHERE {
  # Investors and their risk tolerance
  ?investor rdf:type wm:Investor .
  OPTIONAL { ?investor wm:riskTolerance ?riskTolerance . }

  # Aggregate cash flow per investor (net and average amount)
  {
    SELECT ?investor (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlowPerInvestor) (AVG(xsd:decimal(?cfAmount)) AS ?cashFlowAmount)
    WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?investor .
      ?cf wm:amount ?cfAmount .
    }
    GROUP BY ?investor
  }

  # Aggregate total holding value per investor
  {
    SELECT ?investor (SUM(xsd:decimal(?holdingValue)) AS ?totalHoldingValue)
    WHERE {
      ?holding rdf:type wm:PortfolioHolding .
      ?holding wm:heldByInvestor ?investor .
      ?holding wm:currentValue ?holdingValue .
    }
    GROUP BY ?investor
  }

  # Aggregate goal progress per investor
  {
    SELECT ?investor (AVG(xsd:decimal(?progressPct)) AS ?goalProgress)
    WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?investor .
      ?goal wm:progressPct ?progressPct .
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTol
       (AVG(xsd:decimal(?netCashFlow)) AS ?avgNetCashFlow)
       (AVG(xsd:decimal(?cfAmt)) AS ?avgCashFlowAmount)
       (AVG(xsd:decimal(?totalRebalanceAmt)) AS ?avgTotalRebalanceAmt)
       (AVG(xsd:decimal(?totalSectorInv)) AS ?avgTotalSectorInvestment)
WHERE {
  # Investor and risk tolerance
  ?investor rdf:type wm:Investor .
  ?investor wm:riskTolerance ?riskTol .

  # Cash flow records (for average cash‑flow amount)
  OPTIONAL {
    ?cf rdf:type wm:CashFlow .
    ?cf wm:hasCashFlowOfInvestor ?investor .
    ?cf wm:amount ?cfAmt .
  }

  # Aggregate net cash flow per investor
  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?cfAmtSum)) AS ?netCashFlow) WHERE {
      ?cfSum rdf:type wm:CashFlow .
      ?cfSum wm:hasCashFlowOfInvestor ?investor .
      ?cfSum wm:amount ?cfAmtSum .
    } GROUP BY ?investor
  }

  # Rebalancing actions (for total rebalance amount per investor)
  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?rebAmt)) AS ?totalRebalanceAmt) WHERE {
      ?reb rdf:type wm:RebalancingAction .
      ?reb wm:rebalancingActionOfInvestor ?investor .
      ?reb wm:amount ?rebAmt .
    } GROUP BY ?investor
  }

  # Sector allocations (for total sector investment per investor)
  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?sectorInv)) AS ?totalSectorInv) WHERE {
      ?sa rdf:type wm:SectorAllocation .
      ?sa wm:allocationOfInvestor ?investor .
      ?sa wm:totalInvestment ?sectorInv .
    } GROUP BY ?investor
  }
}
GROUP BY ?riskTol

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance 
       (AVG(xsd:decimal(?netCashFlow)) AS ?avgNetCashFlow) 
       (AVG(xsd:decimal(?cashFlowAmt)) AS ?avgCashFlowAmt) 
       (AVG(xsd:decimal(?totalRebalanceAmt)) AS ?avgTotalRebalanceAmt) 
       (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore)
WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:riskTolerance ?riskTolerance .

  {
    SELECT ?investor (SUM(xsd:decimal(?cfAmt)) AS ?netCashFlow) (AVG(xsd:decimal(?cfAmt)) AS ?cashFlowAmt)
    WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?investor .
      ?cf wm:amount ?cfAmt .
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (SUM(xsd:decimal(?rebAmt)) AS ?totalRebalanceAmt)
    WHERE {
      ?reb rdf:type wm:RebalancingAction .
      ?reb wm:rebalancingActionOfInvestor ?investor .
      ?reb wm:amount ?rebAmt .
    }
    GROUP BY ?investor
  }

  OPTIONAL {
    ?ph rdf:type wm:PortfolioHealth .
    ?ph wm:healthOfInvestor ?investor .
    ?ph wm:riskScore ?riskScore .
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (AVG(?netCashFlow) AS ?avgNetCashFlow)
       (AVG(?cfAmount) AS ?avgCashFlowAmount)
       (AVG(?totalHoldingValue) AS ?avgTotalHoldingValue)
       (AVG(?riskScoreVal) AS ?avgRiskScore)
WHERE {
  ?investor rdf:type wm:Investor .
  OPTIONAL { ?investor wm:riskTolerance ?riskTolerance . }

  # Net cash flow per investor
  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?cfAmt)) AS ?netCashFlow) WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:hasCashFlowOfInvestor ?investor .
      ?cf wm:amount ?cfAmt .
    } GROUP BY ?investor
  }

  # Total holding value per investor
  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?holdVal)) AS ?totalHoldingValue) WHERE {
      ?hold rdf:type wm:PortfolioHolding .
      ?hold wm:heldByInvestor ?investor .
      ?hold wm:currentValue ?holdVal .
    } GROUP BY ?investor
  }

  # Risk score per investor
  OPTIONAL {
    SELECT ?investor (xsd:decimal(?rs) AS ?riskScoreVal) WHERE {
      ?ph rdf:type wm:PortfolioHealth .
      ?ph wm:healthOfInvestor ?investor .
      ?ph wm:riskScore ?rs .
    } GROUP BY ?investor
  }

  # Cash flow amount for average cash‑flow amount
  OPTIONAL {
    ?cf2 rdf:type wm:CashFlow .
    ?cf2 wm:hasCashFlowOfInvestor ?investor .
    ?cf2 wm:amount ?cfAmt2 .
    BIND(xsd:decimal(?cfAmt2) AS ?cfAmount)
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance 
       (AVG(?totalCashFlow) AS ?avgNetCashFlow) 
       (AVG(?avgCashFlowAmount) AS ?avgCashFlowAmount) 
       (AVG(?totalRebalanceAmount) AS ?avgTotalRebalanceAmount) 
       (AVG(?avgGoalProgress) AS ?avgGoalProgress)
WHERE {
  ?inv rdf:type wm:Investor .
  ?inv wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskTolerance .

  {
    SELECT ?investor (SUM(xsd:decimal(?cfAmount)) AS ?totalCashFlow) (AVG(xsd:decimal(?cfAmount)) AS ?avgCashFlowAmount)
    WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?investor .
      ?cf wm:amount ?cfAmount .
    } GROUP BY ?investor
  }

  {
    SELECT ?investor (SUM(xsd:decimal(?rebAmount)) AS ?totalRebalanceAmount)
    WHERE {
      ?reb rdf:type wm:RebalancingAction .
      ?reb wm:rebalancingActionOfInvestor ?investor .
      ?reb wm:amount ?rebAmount .
    } GROUP BY ?investor
  }

  {
    SELECT ?investor (AVG(xsd:decimal(?prog)) AS ?avgGoalProgress)
    WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?investor .
      ?goal wm:progressPct ?prog .
    } GROUP BY ?investor
  }

  BIND(?inv AS ?investor)
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTol
       (AVG(xsd:decimal(?totalCashFlow)) AS ?avgNetCashFlow)
       (AVG(xsd:decimal(?cfAmount)) AS ?avgCashFlowAmount)
       (AVG(xsd:decimal(?totalSectorInv)) AS ?avgTotalSectorInvestment)
       (AVG(xsd:decimal(?progress)) AS ?avgGoalProgress)
WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:riskTolerance ?riskTol .

  # Individual cash‑flow amounts
  OPTIONAL {
    ?cf rdf:type wm:CashFlow .
    ?cf wm:hasCashFlowOfInvestor ?investor .
    ?cf wm:amount ?cfAmount .
  }

  # Total cash‑flow per investor (net cash flow)
  OPTIONAL {
    {
      SELECT ?investor (SUM(xsd:decimal(?cfAmt)) AS ?totalCashFlow)
      WHERE {
        ?cf2 rdf:type wm:CashFlow .
        ?cf2 wm:hasCashFlowOfInvestor ?investor .
        ?cf2 wm:amount ?cfAmt .
      }
      GROUP BY ?investor
    }
  }

  # Total sector investment per investor
  OPTIONAL {
    {
      SELECT ?investor (SUM(xsd:decimal(?invAmt)) AS ?totalSectorInv)
      WHERE {
        ?sa rdf:type wm:SectorAllocation .
        ?sa wm:allocationOfInvestor ?investor .
        ?sa wm:totalInvestment ?invAmt .
      }
      GROUP BY ?investor
    }
  }

  # Investment goal progress
  OPTIONAL {
    ?goal rdf:type wm:InvestmentGoal .
    ?goal wm:belongsToInvestor ?investor .
    ?goal wm:progressPct ?progress .
  }
}
GROUP BY ?riskTol

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (AVG(?netCashFlow) AS ?avgNetCashFlow)
       (AVG(?avgCashFlowAmt) AS ?avgCashFlowAmount)
       (AVG(?totalSectorInv) AS ?avgTotalSectorInvestment)
       (AVG(?riskScore) AS ?avgRiskScore)
WHERE {
  ?inv rdf:type wm:Investor .
  ?inv wm:investorId ?investorId .
  OPTIONAL { ?inv wm:riskTolerance ?riskTolerance . }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlow) (AVG(xsd:decimal(?cfAmount)) AS ?avgCashFlowAmt)
    WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?inv .
      ?inv wm:investorId ?investorId .
      ?cf wm:amount ?cfAmount .
    }
    GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?totalInv)) AS ?totalSectorInv)
    WHERE {
      ?sa rdf:type wm:SectorAllocation .
      ?sa wm:allocationOfInvestor ?inv .
      ?inv wm:investorId ?investorId .
      ?sa wm:totalInvestment ?totalInv .
    }
    GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (xsd:decimal(?riskScore) AS ?riskScore)
    WHERE {
      ?ph rdf:type wm:PortfolioHealth .
      ?ph wm:healthOfInvestor ?inv .
      ?inv wm:investorId ?investorId .
      ?ph wm:riskScore ?riskScore .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance ?avgNetCashFlow ?avgCashFlowAmount ?avgRiskScore ?avgGoalProgress WHERE {
  {
    SELECT ?riskTolerance (AVG(xsd:decimal(?netCashFlow)) AS ?avgNetCashFlow) WHERE {
      ?inv rdf:type wm:Investor .
      ?inv wm:riskTolerance ?riskTolerance .
      {
        SELECT ?inv (SUM(xsd:decimal(?amt)) AS ?netCashFlow) WHERE {
          ?cf rdf:type wm:CashFlow .
          ?cf wm:cashFlowOfInvestor ?inv .
          ?cf wm:amount ?amt .
        } GROUP BY ?inv
      }
    } GROUP BY ?riskTolerance
  }
  {
    SELECT ?riskTolerance (AVG(xsd:decimal(?amt)) AS ?avgCashFlowAmount) WHERE {
      ?inv rdf:type wm:Investor .
      ?inv wm:riskTolerance ?riskTolerance .
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?inv .
      ?cf wm:amount ?amt .
    } GROUP BY ?riskTolerance
  }
  {
    SELECT ?riskTolerance (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore) WHERE {
      ?inv rdf:type wm:Investor .
      ?inv wm:riskTolerance ?riskTolerance .
      ?ph rdf:type wm:PortfolioHealth .
      ?ph wm:healthOfInvestor ?inv .
      ?ph wm:riskScore ?riskScore .
    } GROUP BY ?riskTolerance
  }
  {
    SELECT ?riskTolerance (AVG(xsd:decimal(?goalProg)) AS ?avgGoalProgress) WHERE {
      ?inv rdf:type wm:Investor .
      ?inv wm:riskTolerance ?riskTolerance .
      {
        SELECT ?inv (AVG(xsd:decimal(?prog)) AS ?goalProg) WHERE {
          ?goal rdf:type wm:InvestmentGoal .
          ?goal wm:belongsToInvestor ?inv .
          ?goal wm:progressPct ?prog .
        } GROUP BY ?inv
      }
    } GROUP BY ?riskTolerance
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (AVG(xsd:decimal(?totalHoldingValue)) AS ?avgTotalHoldingValue)
       (AVG(xsd:decimal(?avgHoldingReturn)) AS ?avgHoldingReturn)
       (AVG(xsd:decimal(?totalRebalanceAmount)) AS ?avgTotalRebalanceAmount)
       (AVG(xsd:decimal(?totalSectorInvestment)) AS ?avgTotalSectorInvestment)
WHERE {
  {
    SELECT ?investor ?riskTolerance ?totalHoldingValue ?avgHoldingReturn ?totalRebalanceAmount ?totalSectorInvestment WHERE {
      ?investor rdf:type wm:Investor .

      OPTIONAL { ?investor wm:riskTolerance ?riskTolLiteral . }
      BIND(COALESCE(?riskTolLiteral, "NULL") AS ?riskTolerance)

      # Total holding value and average holding return per investor
      {
        SELECT ?investor (SUM(xsd:decimal(?currVal)) AS ?totalHoldingValue) (AVG(xsd:decimal(?holdingReturn)) AS ?avgHoldingReturn) WHERE {
          ?investor wm:hasHolding ?holding .
          ?holding rdf:type wm:PortfolioHolding .
          ?holding wm:currentValue ?currVal .
          OPTIONAL { ?holding wm:cost ?cost . }
          BIND( IF(BOUND(?cost), (xsd:decimal(?currVal) - xsd:decimal(?cost)) / xsd:decimal(?cost), UNDEF) AS ?holdingReturn )
        } GROUP BY ?investor
      }

      # Total rebalance amount per investor
      {
        SELECT ?investor (SUM(xsd:decimal(?rebAmount)) AS ?totalRebalanceAmount) WHERE {
          ?investor wm:hasRebalancingAction ?reb .
          ?reb rdf:type wm:RebalancingAction .
          ?reb wm:amount ?rebAmount .
        } GROUP BY ?investor
      }

      # Total sector investment per investor
      {
        SELECT ?investor (SUM(xsd:decimal(?totalInv)) AS ?totalSectorInvestment) WHERE {
          ?investor wm:hasSectorAllocation ?secAlloc .
          ?secAlloc rdf:type wm:SectorAllocation .
          ?secAlloc wm:totalInvestment ?totalInv .
        } GROUP BY ?investor
      }
    }
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (AVG(xsd:decimal(?netCashFlow)) AS ?avgNetCashFlow)
       (AVG(xsd:decimal(?avgCashFlowAmt)) AS ?avgCashFlowAmount)
       (AVG(xsd:decimal(?totalSectorInv)) AS ?avgTotalSectorInvestment)
       (AVG(xsd:decimal(?avgScenarioShift)) AS ?avgScenarioAllocationShift)
WHERE {
  ?investor rdf:type wm:Investor .
  OPTIONAL {
    ?investor wm:hasRiskTolerance ?rt .
    ?rt rdfs:label ?riskTolerance .
  }

  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?cfAmt)) AS ?netCashFlow) (AVG(xsd:decimal(?cfAmt)) AS ?avgCashFlowAmt)
    WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?investor .
      ?cf wm:amount ?cfAmt .
    } GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?totalInv)) AS ?totalSectorInv)
    WHERE {
      ?sa rdf:type wm:SectorAllocation .
      ?sa wm:allocationOfInvestor ?investor .
      ?sa wm:totalInvestment ?totalInv .
    } GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (AVG(xsd:decimal(?shift)) AS ?avgScenarioShift)
    WHERE {
      ?sr rdf:type wm:ScenarioRebalancing .
      ?sr wm:scenarioRebalancingOfInvestor ?investor .
      ?sr wm:newAllocationPct ?newPct .
      ?sr wm:currentAllocationPct ?curPct .
      BIND(xsd:decimal(?newPct) - xsd:decimal(?curPct) AS ?shift)
    } GROUP BY ?investor
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskToleranceLabel 
       (AVG(xsd:decimal(?totalHoldingValue)) AS ?avgTotalHoldingValue) 
       (AVG(xsd:decimal(?avgHoldingReturn)) AS ?avgHoldingReturn) 
       (AVG(xsd:decimal(?totalSectorInvestment)) AS ?avgTotalSectorInvestment) 
       (AVG(xsd:decimal(?avgScenarioShift)) AS ?avgScenarioAllocationShift)
WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .
  ?investor wm:hasRiskTolerance ?riskTol .
  ?riskTol rdfs:label ?riskToleranceLabel .

  {
    SELECT ?investorId (SUM(xsd:decimal(?currVal)) AS ?totalHoldingValue) (AVG(xsd:decimal(?returnPct)) AS ?avgHoldingReturn)
    WHERE {
      ?holding rdf:type wm:PortfolioHolding .
      ?holding wm:heldByInvestor ?investor .
      ?holding wm:currentValue ?currVal .
      OPTIONAL {
        ?holding wm:cost ?cost .
        ?holding wm:returnsPct ?returnPct .
        FILTER(BOUND(?cost))
      }
    }
    GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?totalInv)) AS ?totalSectorInvestment)
    WHERE {
      ?sectorAlloc rdf:type wm:SectorAllocation .
      ?sectorAlloc wm:allocationOfInvestor ?investor .
      ?sectorAlloc wm:totalInvestment ?totalInv .
    }
    GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (AVG(xsd:decimal(?shift)) AS ?avgScenarioShift)
    WHERE {
      ?scenarioReb rdf:type wm:ScenarioRebalancing .
      ?scenarioReb wm:scenarioRebalancingOfInvestor ?investor .
      ?scenarioReb wm:newAllocationPct ?newPct .
      ?scenarioReb wm:currentAllocationPct ?curPct .
      BIND((xsd:decimal(?newPct) - xsd:decimal(?curPct)) AS ?shift)
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?riskToleranceLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (AVG(xsd:decimal(?totalHoldingValue)) AS ?avgTotalHoldingValue)
       (AVG(xsd:decimal(?avgHoldingReturn)) AS ?avgHoldingReturn)
       (AVG(xsd:decimal(?totalRebalanceAmount)) AS ?avgTotalRebalanceAmount)
       (AVG(xsd:decimal(?avgScenarioAllocationShift)) AS ?avgScenarioAllocationShift)
WHERE {
  ?investor rdf:type wm:Investor .

  OPTIONAL {
    ?investor wm:hasRiskTolerance ?rt .
    OPTIONAL { ?rt rdfs:label ?rtLabel . }
  }
  BIND( COALESCE(?rtLabel, "NULL") AS ?riskTolerance )

  # Holdings aggregation per investor
  OPTIONAL {
    {
      SELECT ?investor
             (SUM(xsd:decimal(?currVal)) AS ?totalHoldingValue)
             (AVG(xsd:decimal(?holdingReturn)) AS ?avgHoldingReturn)
      WHERE {
        ?investor wm:hasHolding ?holding .
        ?holding wm:currentValue ?currVal .
        OPTIONAL { ?holding wm:cost ?cost . }
        BIND( IF(BOUND(?cost),
                 (xsd:decimal(?currVal) - xsd:decimal(?cost)) / xsd:decimal(?cost),
                 UNDEF) AS ?holdingReturn )
      }
      GROUP BY ?investor
    }
  }

  # Rebalancing actions aggregation per investor
  OPTIONAL {
    {
      SELECT ?investor
             (SUM(xsd:decimal(?rebAmount)) AS ?totalRebalanceAmount)
      WHERE {
        ?investor wm:hasRebalancingAction ?reb .
        ?reb wm:amount ?rebAmount .
      }
      GROUP BY ?investor
    }
  }

  # Scenario rebalancing aggregation per investor
  OPTIONAL {
    {
      SELECT ?investor
             (AVG(xsd:decimal(?allocShift)) AS ?avgScenarioAllocationShift)
      WHERE {
        ?investor wm:hasScenarioRebalancing ?sr .
        ?sr wm:newAllocationPct ?newAlloc .
        ?sr wm:currentAllocationPct ?curAlloc .
        BIND( (xsd:decimal(?newAlloc) - xsd:decimal(?curAlloc)) AS ?allocShift )
      }
      GROUP BY ?investor
    }
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?compositeScore WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?cashFlowSum) WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:investorId ?investorId .
      ?cf wm:amount ?cfAmount .
    } GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?rebAmount)) AS ?rebalanceSum) WHERE {
      ?ra rdf:type wm:RebalancingAction .
      ?ra wm:investorId ?investorId .
      ?ra wm:amount ?rebAmount .
    } GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?sectorInv)) AS ?sectorInvSum) WHERE {
      ?sa rdf:type wm:SectorAllocation .
      ?sa wm:investorId ?investorId .
      ?sa wm:totalInvestment ?sectorInv .
    } GROUP BY ?investorId
  }
  BIND ((xsd:decimal(?cashFlowSum) + xsd:decimal(?rebalanceSum) + xsd:decimal(?sectorInvSum)) AS ?compositeScore)
}
ORDER BY DESC(?compositeScore) ASC(?investorId)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (AVG(xsd:decimal(?netCashFlow)) AS ?avgNetCashFlow)
       (AVG(xsd:decimal(?cfAmount)) AS ?avgCashFlowAmount)
       (AVG(xsd:decimal(?allocShift)) AS ?avgAllocShift)
       (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore)
WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:riskTolerance ?riskTolerance .

  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?cfAmt)) AS ?netCashFlow)
    WHERE {
      ?investor wm:hasCashFlow ?cf .
      ?cf wm:amount ?cfAmt .
    }
    GROUP BY ?investor
  }

  OPTIONAL {
    ?investor wm:hasCashFlow ?cf2 .
    ?cf2 wm:amount ?cfAmount .
  }

  OPTIONAL {
    ?investor wm:hasScenarioRebalancing ?sr .
    ?sr wm:newAllocationPct ?newPct .
    ?sr wm:currentAllocationPct ?curPct .
    BIND ((xsd:decimal(?newPct) - xsd:decimal(?curPct)) AS ?allocShift)
  }

  OPTIONAL {
    ?investor wm:hasPortfolioHealth ?ph .
    ?ph wm:riskScore ?riskScore .
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?invId ?compositeScore WHERE {
  {
    SELECT ?invId ?totalGain ?totalShift WHERE {
      {
        SELECT ?invId (SUM(xsd:decimal(?currVal) - xsd:decimal(?cost)) AS ?totalGain) WHERE {
          ?holding rdf:type wm:PortfolioHolding .
          ?holding wm:investorId ?invId .
          ?holding wm:cost ?cost .
          ?holding wm:currentValue ?currVal .
        } GROUP BY ?invId
      }
      {
        SELECT ?invId (SUM(xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc)) AS ?totalShift) WHERE {
          ?scenario rdf:type wm:ScenarioRebalancing .
          ?scenario wm:investorId ?invId .
          ?scenario wm:newAllocationPct ?newAlloc .
          ?scenario wm:currentAllocationPct ?currAlloc .
        } GROUP BY ?invId
      }
    }
  }
  {
    SELECT (MIN(?g) AS ?minGain) (MAX(?g) AS ?maxGain) (MIN(?s) AS ?minShift) (MAX(?s) AS ?maxShift) WHERE {
      {
        SELECT ?invId (SUM(xsd:decimal(?currVal) - xsd:decimal(?cost)) AS ?g) WHERE {
          ?holding rdf:type wm:PortfolioHolding .
          ?holding wm:investorId ?invId .
          ?holding wm:cost ?cost .
          ?holding wm:currentValue ?currVal .
        } GROUP BY ?invId
      }
      {
        SELECT ?invId (SUM(xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc)) AS ?s) WHERE {
          ?scenario rdf:type wm:ScenarioRebalancing .
          ?scenario wm:investorId ?invId .
          ?scenario wm:newAllocationPct ?newAlloc .
          ?scenario wm:currentAllocationPct ?currAlloc .
        } GROUP BY ?invId
      }
    }
  }
  BIND( IF(?maxGain != ?minGain,
           (xsd:decimal(?totalGain) - xsd:decimal(?minGain)) / (xsd:decimal(?maxGain) - xsd:decimal(?minGain)),
           0) AS ?normGain )
  BIND( IF(?maxShift != ?minShift,
           (xsd:decimal(?totalShift) - xsd:decimal(?minShift)) / (xsd:decimal(?maxShift) - xsd:decimal(?minShift)),
           0) AS ?normShift )
  BIND( ((?normGain + ?normShift) / 2) * 100 AS ?compositeScore )
}
ORDER BY DESC(?compositeScore) ASC(?invId)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?compositeScore WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .

  {
    SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlow) WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:investorId ?investorId .
      ?cf wm:amount ?cfAmount .
    } GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?rebAmount)) AS ?totalRebalance) WHERE {
      ?reb rdf:type wm:RebalancingAction .
      ?reb wm:investorId ?investorId .
      ?reb wm:amount ?rebAmount .
    } GROUP BY ?investorId
  }

  {
    SELECT ?investorId (AVG(xsd:decimal(?shortfall)) AS ?avgShortfall) WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:investorId ?investorId .
      ?goal wm:shortfall ?shortfall .
    } GROUP BY ?investorId
  }

  BIND( (xsd:decimal(?netCashFlow) + xsd:decimal(?totalRebalance) - xsd:decimal(?avgShortfall)) AS ?compositeScore )
  FILTER(BOUND(?netCashFlow) && BOUND(?totalRebalance) && BOUND(?avgShortfall))
}
ORDER BY DESC(?compositeScore) ASC(?investorId)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?transactionRebalanceIndex WHERE {
  {
    SELECT ?investorId ?netCashFlow ?totalRebalanceAmt ?totalScenarioShift WHERE {
      {
        SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlow) WHERE {
          ?cashFlow rdf:type wm:CashFlow .
          ?cashFlow wm:cashFlowOfInvestor ?inv .
          ?inv wm:investorId ?investorId .
          ?cashFlow wm:amount ?cfAmount .
        } GROUP BY ?investorId
      }
      {
        SELECT ?investorId (SUM(xsd:decimal(?rebAmount)) AS ?totalRebalanceAmt) WHERE {
          ?rebAction rdf:type wm:RebalancingAction .
          ?rebAction wm:rebalancingActionOfInvestor ?inv .
          ?inv wm:investorId ?investorId .
          ?rebAction wm:amount ?rebAmount .
        } GROUP BY ?investorId
      }
      {
        SELECT ?investorId (SUM( (xsd:decimal(?newAlloc) - xsd:decimal(?curAlloc)) ) AS ?totalScenarioShift) WHERE {
          ?scenarioReb rdf:type wm:ScenarioRebalancing .
          ?scenarioReb wm:scenarioRebalancingOfInvestor ?inv .
          ?inv wm:investorId ?investorId .
          ?scenarioReb wm:newAllocationPct ?newAlloc .
          ?scenarioReb wm:currentAllocationPct ?curAlloc .
        } GROUP BY ?investorId
      }
    }
  }
  {
    SELECT (MIN(?netCashFlow) AS ?minNet) (MAX(?netCashFlow) AS ?maxNet)
           (MIN(?totalRebalanceAmt) AS ?minReb) (MAX(?totalRebalanceAmt) AS ?maxReb)
           (MIN(?totalScenarioShift) AS ?minShift) (MAX(?totalScenarioShift) AS ?maxShift) WHERE {
      {
        SELECT ?investorId ?netCashFlow ?totalRebalanceAmt ?totalScenarioShift WHERE {
          {
            SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlow) WHERE {
              ?cashFlow rdf:type wm:CashFlow .
              ?cashFlow wm:cashFlowOfInvestor ?inv .
              ?inv wm:investorId ?investorId .
              ?cashFlow wm:amount ?cfAmount .
            } GROUP BY ?investorId
          }
          {
            SELECT ?investorId (SUM(xsd:decimal(?rebAmount)) AS ?totalRebalanceAmt) WHERE {
              ?rebAction rdf:type wm:RebalancingAction .
              ?rebAction wm:rebalancingActionOfInvestor ?inv .
              ?inv wm:investorId ?investorId .
              ?rebAction wm:amount ?rebAmount .
            } GROUP BY ?investorId
          }
          {
            SELECT ?investorId (SUM( (xsd:decimal(?newAlloc) - xsd:decimal(?curAlloc)) ) AS ?totalScenarioShift) WHERE {
              ?scenarioReb rdf:type wm:ScenarioRebalancing .
              ?scenarioReb wm:scenarioRebalancingOfInvestor ?inv .
              ?inv wm:investorId ?investorId .
              ?scenarioReb wm:newAllocationPct ?newAlloc .
              ?scenarioReb wm:currentAllocationPct ?curAlloc .
            } GROUP BY ?investorId
          }
        }
      }
    }
  }
  BIND( IF( (?maxNet - ?minNet) = 0, 0, ( ?netCashFlow - ?minNet ) / ( ?maxNet - ?minNet ) ) AS ?normNet )
  BIND( IF( (?maxReb - ?minReb) = 0, 0, ( ?totalRebalanceAmt - ?minReb ) / ( ?maxReb - ?minReb ) ) AS ?normReb )
  BIND( IF( (?maxShift - ?minShift) = 0, 0, ( ?totalScenarioShift - ?minShift ) / ( ?maxShift - ?minShift ) ) AS ?normShift )
  BIND( ( ( ?normNet + ?normReb + ?normShift ) / 3 ) * 100 AS ?transactionRebalanceIndex )
}
ORDER BY DESC(?transactionRebalanceIndex) ASC(?investorId)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId (?compositeScore AS ?compositeScore)
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
    WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?inv .
      ?inv rdf:type wm:Investor .
      ?inv wm:investorId ?investorId .
      ?cf wm:amount ?amount .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?totalInv)) AS ?totalSectorInv)
    WHERE {
      ?sa rdf:type wm:SectorAllocation .
      ?sa wm:allocationOfInvestor ?inv .
      ?inv rdf:type wm:Investor .
      ?inv wm:investorId ?investorId .
      ?sa wm:totalInvestment ?totalInv .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?shortfall)) AS ?avgGoalShortfall)
    WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?inv .
      ?inv rdf:type wm:Investor .
      ?inv wm:investorId ?investorId .
      ?goal wm:shortfall ?shortfall .
    }
    GROUP BY ?investorId
  }
  BIND((?netCashFlow + ?totalSectorInv - ?avgGoalShortfall) AS ?compositeScore)
}
ORDER BY DESC(?compositeScore) ASC(?investorId)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?compositeScore WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?netCashFlow) WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?inv .
      ?inv wm:investorId ?investorId .
      ?cf wm:amount ?amount .
    } GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?gain)) AS ?totalHoldingGain) WHERE {
      ?h rdf:type wm:PortfolioHolding .
      ?h wm:heldByInvestor ?inv .
      ?inv wm:investorId ?investorId .
      ?h wm:cost ?cost .
      ?h wm:currentValue ?currentValue .
      BIND( (xsd:decimal(?currentValue) - xsd:decimal(?cost)) AS ?gain )
    } GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?shortfall)) AS ?avgGoalShortfall) WHERE {
      ?g rdf:type wm:InvestmentGoal .
      ?g wm:belongsToInvestor ?inv .
      ?inv wm:investorId ?investorId .
      ?g wm:shortfall ?shortfall .
    } GROUP BY ?investorId
  }
  BIND( (?netCashFlow + ?totalHoldingGain - ?avgGoalShortfall) AS ?compositeScore )
}
ORDER BY DESC(?compositeScore) ASC(?investorId)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?compositeScore WHERE {
  {
    SELECT ?investorId ?cashFlowSum ?sectorInvestSum ?allocShiftSum WHERE {
      {
        SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cashFlowSum) WHERE {
          ?cf rdf:type wm:CashFlow .
          ?cf wm:amount ?amount .
          ?cf wm:investorId ?investorId .
        } GROUP BY ?investorId
      }
      {
        SELECT ?investorId (SUM(xsd:decimal(?totalInv)) AS ?sectorInvestSum) WHERE {
          ?sa rdf:type wm:SectorAllocation .
          ?sa wm:totalInvestment ?totalInv .
          ?sa wm:investorId ?investorId .
        } GROUP BY ?investorId
      }
      {
        SELECT ?investorId (SUM(xsd:decimal(?new) - xsd:decimal(?curr)) AS ?allocShiftSum) WHERE {
          ?sr rdf:type wm:ScenarioRebalancing .
          ?sr wm:newAllocationPct ?new .
          ?sr wm:currentAllocationPct ?curr .
          ?sr wm:investorId ?investorId .
        } GROUP BY ?investorId
      }
    }
  }
  {
    SELECT (MIN(?c) AS ?cashMin) (MAX(?c) AS ?cashMax)
           (MIN(?s) AS ?sectorMin) (MAX(?s) AS ?sectorMax)
           (MIN(?a) AS ?shiftMin) (MAX(?a) AS ?shiftMax) WHERE {
      {
        SELECT ?c ?s ?a WHERE {
          {
            SELECT (SUM(xsd:decimal(?amount)) AS ?c) WHERE {
              ?cf rdf:type wm:CashFlow .
              ?cf wm:amount ?amount .
            }
          }
          {
            SELECT (SUM(xsd:decimal(?totalInv)) AS ?s) WHERE {
              ?sa rdf:type wm:SectorAllocation .
              ?sa wm:totalInvestment ?totalInv .
            }
          }
          {
            SELECT (SUM(xsd:decimal(?new) - xsd:decimal(?curr)) AS ?a) WHERE {
              ?sr rdf:type wm:ScenarioRebalancing .
              ?sr wm:newAllocationPct ?new .
              ?sr wm:currentAllocationPct ?curr .
            }
          }
        }
      }
    }
  }
  BIND( IF(?cashMax = ?cashMin, 0, (xsd:decimal(?cashFlowSum) - ?cashMin) / (?cashMax - ?cashMin) ) AS ?normCash )
  BIND( IF(?sectorMax = ?sectorMin, 0, (xsd:decimal(?sectorInvestSum) - ?sectorMin) / (?sectorMax - ?sectorMin) ) AS ?normSector )
  BIND( IF(?shiftMax = ?shiftMin, 0, (xsd:decimal(?allocShiftSum) - ?shiftMin) / (?shiftMax - ?shiftMin) ) AS ?normShift )
  BIND( ( ( ?normCash + ?normSector + ?normShift ) / 3 ) * 100 AS ?compositeScore )
}
ORDER BY DESC(?compositeScore) ASC(?investorId)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?compositeScore WHERE {
  {
    SELECT ?investorId ?cashFlowSum ?rebalanceSum ?riskScore WHERE {
      {
        SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?cashFlowSum) WHERE {
          ?cf rdf:type wm:CashFlow .
          ?cf wm:investorId ?investorId .
          ?cf wm:amount ?cfAmount .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId (SUM(xsd:decimal(?rebAmount)) AS ?rebalanceSum) WHERE {
          ?ra rdf:type wm:RebalancingAction .
          ?ra wm:investorId ?investorId .
          ?ra wm:amount ?rebAmount .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId ?riskScore WHERE {
          ?ph rdf:type wm:PortfolioHealth .
          ?ph wm:investorId ?investorId .
          ?ph wm:riskScore ?riskScore .
        }
        GROUP BY ?investorId ?riskScore
      }
    }
  }
  FILTER(BOUND(?cashFlowSum) && BOUND(?rebalanceSum) && BOUND(?riskScore))

  {
    SELECT (MIN(?cashFlowSum) AS ?minCash) (MAX(?cashFlowSum) AS ?maxCash)
           (MIN(?rebalanceSum) AS ?minReb) (MAX(?rebalanceSum) AS ?maxReb)
           (MIN(?riskScore) AS ?minRisk) (MAX(?riskScore) AS ?maxRisk) WHERE {
      {
        SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?cashFlowSum) WHERE {
          ?cf rdf:type wm:CashFlow .
          ?cf wm:investorId ?investorId .
          ?cf wm:amount ?cfAmount .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId (SUM(xsd:decimal(?rebAmount)) AS ?rebalanceSum) WHERE {
          ?ra rdf:type wm:RebalancingAction .
          ?ra wm:investorId ?investorId .
          ?ra wm:amount ?rebAmount .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId ?riskScore WHERE {
          ?ph rdf:type wm:PortfolioHealth .
          ?ph wm:investorId ?investorId .
          ?ph wm:riskScore ?riskScore .
        }
        GROUP BY ?investorId ?riskScore
      }
    }
  }

  BIND( IF(?maxCash != ?minCash,
           (xsd:decimal(?cashFlowSum) - xsd:decimal(?minCash)) / (xsd:decimal(?maxCash) - xsd:decimal(?minCash)),
           0) AS ?normCash )
  BIND( IF(?maxReb != ?minReb,
           (xsd:decimal(?rebalanceSum) - xsd:decimal(?minReb)) / (xsd:decimal(?maxReb) - xsd:decimal(?minReb)),
           0) AS ?normReb )
  BIND( IF(?maxRisk != ?minRisk,
           (xsd:decimal(?riskScore) - xsd:decimal(?minRisk)) / (xsd:decimal(?maxRisk) - xsd:decimal(?minRisk)),
           0) AS ?normRisk )
  BIND( ((?normCash + ?normReb + ?normRisk) / 3) * 100 AS ?compositeScore )
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?compositeScore WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cashFlowSum) WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:investorId ?investorId .
      ?cf wm:amount ?amount .
    } GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?gain)) AS ?holdingGainSum) WHERE {
      ?ph rdf:type wm:PortfolioHolding .
      ?ph wm:investorId ?investorId .
      ?ph wm:cost ?cost .
      ?ph wm:currentValue ?curr .
      BIND (xsd:decimal(?curr) - xsd:decimal(?cost) AS ?gain)
    } GROUP BY ?investorId
  }
  {
    SELECT ?investorId (MAX(xsd:decimal(?riskScore)) AS ?riskScore) WHERE {
      ?phl rdf:type wm:PortfolioHealth .
      ?phl wm:investorId ?investorId .
      ?phl wm:riskScore ?riskScore .
    } GROUP BY ?investorId
  }
  {
    SELECT (MIN(?cSum) AS ?minCash) (MAX(?cSum) AS ?maxCash) WHERE {
      {
        SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cSum) WHERE {
          ?cf rdf:type wm:CashFlow .
          ?cf wm:investorId ?investorId .
          ?cf wm:amount ?amount .
        } GROUP BY ?investorId
      }
    }
  }
  {
    SELECT (MIN(?gSum) AS ?minGain) (MAX(?gSum) AS ?maxGain) WHERE {
      {
        SELECT ?investorId (SUM(xsd:decimal(?gain)) AS ?gSum) WHERE {
          ?ph rdf:type wm:PortfolioHolding .
          ?ph wm:investorId ?investorId .
          ?ph wm:cost ?cost .
          ?ph wm:currentValue ?curr .
          BIND (xsd:decimal(?curr) - xsd:decimal(?cost) AS ?gain)
        } GROUP BY ?investorId
      }
    }
  }
  {
    SELECT (MIN(?r) AS ?minRisk) (MAX(?r) AS ?maxRisk) WHERE {
      {
        SELECT ?investorId (MAX(xsd:decimal(?riskScore)) AS ?r) WHERE {
          ?phl rdf:type wm:PortfolioHealth .
          ?phl wm:investorId ?investorId .
          ?phl wm:riskScore ?riskScore .
        } GROUP BY ?investorId
      }
    }
  }
  BIND( IF(?maxCash != ?minCash, (?cashFlowSum - ?minCash) / (?maxCash - ?minCash), 0) AS ?normCash )
  BIND( IF(?maxGain != ?minGain, (?holdingGainSum - ?minGain) / (?maxGain - ?minGain), 0) AS ?normGain )
  BIND( IF(?maxRisk != ?minRisk, (?riskScore - ?minRisk) / (?maxRisk - ?minRisk), 0) AS ?normRisk )
  BIND( ((?normCash + ?normGain + ?normRisk) / 3) * 100 AS ?compositeScore )
}
ORDER BY DESC(?compositeScore) ASC(?investorId)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?compositeScore
WHERE {
  # --- per‑investor aggregates ---
  {
    SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?totalCashFlow)
    WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:investorId ?investorId .
      ?cf wm:amount ?cfAmount .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc)) AS ?totalShift)
    WHERE {
      ?sr rdf:type wm:ScenarioRebalancing .
      ?sr wm:investorId ?investorId .
      ?sr wm:newAllocationPct ?newAlloc .
      ?sr wm:currentAllocationPct ?currAlloc .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?shortfall)) AS ?avgShortfall)
    WHERE {
      ?g rdf:type wm:InvestmentGoal .
      ?g wm:investorId ?investorId .
      ?g wm:shortfall ?shortfall .
    }
    GROUP BY ?investorId
  }

  # --- min/max for each component across all qualifying investors ---
  {
    SELECT (MIN(?c) AS ?minCash) (MAX(?c) AS ?maxCash)
    WHERE {
      {
        SELECT ?investorId (SUM(xsd:decimal(?cfAmount2)) AS ?c)
        WHERE {
          ?cf2 rdf:type wm:CashFlow .
          ?cf2 wm:investorId ?investorId .
          ?cf2 wm:amount ?cfAmount2 .
        }
        GROUP BY ?investorId
      }
    }
  }
  {
    SELECT (MIN(?s) AS ?minShift) (MAX(?s) AS ?maxShift)
    WHERE {
      {
        SELECT ?investorId (SUM(xsd:decimal(?new2) - xsd:decimal(?curr2)) AS ?s)
        WHERE {
          ?sr2 rdf:type wm:ScenarioRebalancing .
          ?sr2 wm:investorId ?investorId .
          ?sr2 wm:newAllocationPct ?new2 .
          ?sr2 wm:currentAllocationPct ?curr2 .
        }
        GROUP BY ?investorId
      }
    }
  }
  {
    SELECT (MIN(?sf) AS ?minShort) (MAX(?sf) AS ?maxShort)
    WHERE {
      {
        SELECT ?investorId (AVG(xsd:decimal(?sh)) AS ?sf)
        WHERE {
          ?g2 rdf:type wm:InvestmentGoal .
          ?g2 wm:investorId ?investorId .
          ?g2 wm:shortfall ?sh .
        }
        GROUP BY ?investorId
      }
    }
  }

  # --- normalize components ---
  BIND( ( ?totalCashFlow - ?minCash ) / ( ?maxCash - ?minCash ) AS ?normCash )
  BIND( ( ?totalShift - ?minShift ) / ( ?maxShift - ?minShift ) AS ?normShift )
  BIND( ( ?avgShortfall - ?minShort ) / ( ?maxShort - ?minShort ) AS ?normShort )
  BIND( (1 - ?normShort) AS ?normShortInv )

  # --- composite score ---
  BIND( ( ?normCash + ?normShift + ?normShortInv ) / 3.0 AS ?meanNorm )
  BIND( ?meanNorm * 100 AS ?compositeScore )
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTol 
       (AVG(xsd:decimal(?totalCashFlow)) AS ?avgNetCashFlow) 
       (AVG(xsd:decimal(?avgCashFlowAmt)) AS ?avgCashFlowAmount) 
       (AVG(xsd:decimal(?totalHoldingValue)) AS ?avgTotalHoldingValue) 
       (AVG(xsd:decimal(?totalRebalanceAmt)) AS ?avgTotalRebalanceAmount) 
       (AVG(xsd:decimal(?totalSectorInvestment)) AS ?avgTotalSectorInvestment)
WHERE {
  ?investor rdf:type wm:Investor .
  OPTIONAL { ?investor wm:riskTolerance ?riskTol . }

  OPTIONAL {
    { SELECT ?investor (SUM(xsd:decimal(?amt)) AS ?totalCashFlow) (AVG(xsd:decimal(?amt)) AS ?avgCashFlowAmt)
      WHERE {
        ?investor wm:hasCashFlow ?cf .
        ?cf rdf:type wm:CashFlow .
        ?cf wm:amount ?amt .
      }
      GROUP BY ?investor
    }
  }

  OPTIONAL {
    { SELECT ?investor (SUM(xsd:decimal(?val)) AS ?totalHoldingValue)
      WHERE {
        ?investor wm:hasHolding ?h .
        ?h rdf:type wm:PortfolioHolding .
        ?h wm:currentValue ?val .
      }
      GROUP BY ?investor
    }
  }

  OPTIONAL {
    { SELECT ?investor (SUM(xsd:decimal(?amt)) AS ?totalRebalanceAmt)
      WHERE {
        ?investor wm:hasRebalancingAction ?ra .
        ?ra rdf:type wm:RebalancingAction .
        ?ra wm:amount ?amt .
      }
      GROUP BY ?investor
    }
  }

  OPTIONAL {
    { SELECT ?investor (SUM(xsd:decimal(?inv)) AS ?totalSectorInvestment)
      WHERE {
        ?investor wm:hasSectorAllocation ?sa .
        ?sa rdf:type wm:SectorAllocation .
        ?sa wm:totalInvestment ?inv .
      }
      GROUP BY ?investor
    }
  }
}
GROUP BY ?riskTol

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (AVG(xsd:decimal(?netCashFlow)) AS ?avgNetCashFlow)
       (AVG(xsd:decimal(?cashFlowAmt)) AS ?avgCashFlowAmount)
       (AVG(xsd:decimal(?totalHoldingValue)) AS ?avgHoldingValue)
       (AVG(xsd:decimal(?totalRebalanceAmt)) AS ?avgRebalanceAmount)
       (AVG(xsd:decimal(?allocShift)) AS ?avgScenarioAllocShift)
WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:riskTolerance ?riskTolerance .

  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?cfAmt)) AS ?netCashFlow) (AVG(xsd:decimal(?cfAmt)) AS ?cashFlowAmt)
    WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?investor .
      ?cf wm:amount ?cfAmt .
    }
    GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?holdVal)) AS ?totalHoldingValue)
    WHERE {
      ?hold rdf:type wm:PortfolioHolding .
      ?hold wm:heldByInvestor ?investor .
      ?hold wm:currentValue ?holdVal .
    }
    GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?rebAmt)) AS ?totalRebalanceAmt)
    WHERE {
      ?reb rdf:type wm:RebalancingAction .
      ?reb wm:rebalancingActionOfInvestor ?investor .
      ?reb wm:amount ?rebAmt .
    }
    GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (AVG(xsd:decimal(?shift)) AS ?allocShift)
    WHERE {
      ?scen rdf:type wm:ScenarioRebalancing .
      ?scen wm:scenarioRebalancingOfInvestor ?investor .
      ?scen wm:newAllocationPct ?newPct .
      ?scen wm:currentAllocationPct ?curPct .
      BIND(xsd:decimal(?newPct) - xsd:decimal(?curPct) AS ?shift)
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (AVG(xsd:decimal(?totalCashFlow)) AS ?avgNetCashFlow)
       (AVG(xsd:decimal(?avgCashFlowAmount)) AS ?avgCashFlowAmount)
       (AVG(xsd:decimal(?totalHoldingValue)) AS ?avgHoldingValue)
       (AVG(xsd:decimal(?totalSectorInvestment)) AS ?avgSectorInvestment)
       (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore)
WHERE {
  ?inv rdf:type wm:Investor .
  ?inv wm:investorId ?investorId .
  ?inv wm:riskTolerance ?riskTolerance .

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?totalCashFlow) (AVG(xsd:decimal(?cfAmount)) AS ?avgCashFlowAmount)
    WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:investorId ?investorId .
      ?cf wm:amount ?cfAmount .
    }
    GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?holdingValue)) AS ?totalHoldingValue)
    WHERE {
      ?ph rdf:type wm:PortfolioHolding .
      ?ph wm:investorId ?investorId .
      ?ph wm:currentValue ?holdingValue .
    }
    GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?totalInv)) AS ?totalSectorInvestment)
    WHERE {
      ?sa rdf:type wm:SectorAllocation .
      ?sa wm:investorId ?investorId .
      ?sa wm:totalInvestment ?totalInv .
    }
    GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (xsd:decimal(?riskScore) AS ?riskScore)
    WHERE {
      ?phl rdf:type wm:PortfolioHealth .
      ?phl wm:investorId ?investorId .
      ?phl wm:riskScore ?riskScore .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?compositeScore WHERE {
  # per‑investor aggregates
  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?totalCash) WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:investorId ?investorId .
      ?cf wm:amount ?amount .
    } GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?new) - xsd:decimal(?cur)) AS ?totalShift) WHERE {
      ?sr rdf:type wm:ScenarioRebalancing .
      ?sr wm:investorId ?investorId .
      ?sr wm:newAllocationPct ?new .
      ?sr wm:currentAllocationPct ?cur .
    } GROUP BY ?investorId
  }
  {
    SELECT ?investorId ?riskScore WHERE {
      ?ph rdf:type wm:PortfolioHealth .
      ?ph wm:investorId ?investorId .
      ?ph wm:riskScore ?riskScore .
    }
  }

  # global mins and maxes
  {
    SELECT (MIN(?c) AS ?minCash) (MAX(?c) AS ?maxCash)
           (MIN(?s) AS ?minShift) (MAX(?s) AS ?maxShift)
           (MIN(?r) AS ?minRisk) (MAX(?r) AS ?maxRisk) WHERE {
      {
        SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?c) WHERE {
          ?cf rdf:type wm:CashFlow .
          ?cf wm:investorId ?investorId .
          ?cf wm:amount ?amount .
        } GROUP BY ?investorId
      }
      {
        SELECT ?investorId (SUM(xsd:decimal(?new) - xsd:decimal(?cur)) AS ?s) WHERE {
          ?sr rdf:type wm:ScenarioRebalancing .
          ?sr wm:investorId ?investorId .
          ?sr wm:newAllocationPct ?new .
          ?sr wm:currentAllocationPct ?cur .
        } GROUP BY ?investorId
      }
      {
        SELECT ?investorId ?r WHERE {
          ?ph rdf:type wm:PortfolioHealth .
          ?ph wm:investorId ?investorId .
          ?ph wm:riskScore ?r .
        }
      }
    }
  }

  # normalization and composite score
  BIND( (xsd:decimal(?totalCash) - xsd:decimal(?minCash)) / (xsd:decimal(?maxCash) - xsd:decimal(?minCash)) AS ?normCash )
  BIND( (xsd:decimal(?totalShift) - xsd:decimal(?minShift)) / (xsd:decimal(?maxShift) - xsd:decimal(?minShift)) AS ?normShift )
  BIND( (xsd:decimal(?riskScore) - xsd:decimal(?minRisk)) / (xsd:decimal(?maxRisk) - xsd:decimal(?minRisk)) AS ?normRisk )
  BIND( ((?normCash + ?normShift + ?normRisk) / 3) * 100 AS ?compositeScore )
}
ORDER BY DESC(?compositeScore) ASC(?investorId)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
