PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (AVG(xsd:decimal(?netCashFlow)) AS ?avgNetCashFlow)
       (AVG(xsd:decimal(?avgCashFlowAmt)) AS ?avgCashFlowAmount)
       (AVG(xsd:decimal(?totalHoldingValue)) AS ?avgTotalHoldingValue)
       (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore)
       (AVG(xsd:decimal(?goalProgress)) AS ?avgGoalProgress)
WHERE {
  ?inv rdf:type wm:Investor .
  ?inv wm:investorId ?investorId .
  ?inv wm:riskTolerance ?riskTolerance .

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?cfAmt)) AS ?netCashFlow) (AVG(xsd:decimal(?cfAmt)) AS ?avgCashFlowAmt)
    WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:amount ?cfAmt .
      ?cf wm:cashFlowOfInvestor ?inv .
    }
    GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?holdVal)) AS ?totalHoldingValue)
    WHERE {
      ?ph rdf:type wm:PortfolioHolding .
      ?ph wm:currentValue ?holdVal .
      ?ph wm:heldByInvestor ?inv .
    }
    GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (AVG(xsd:decimal(?rs)) AS ?riskScore)
    WHERE {
      ?phs rdf:type wm:PortfolioHealth .
      ?phs wm:riskScore ?rs .
      ?phs wm:healthOfInvestor ?inv .
    }
    GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (AVG(xsd:decimal(?prog)) AS ?goalProgress)
    WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:progressPct ?prog .
      ?goal wm:belongsToInvestor ?inv .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance ?avgNetCashFlow ?avgCashFlowAmount ?avgTotalHoldingValue ?avgTotalRebalanceAmount ?avgRiskScore
WHERE {
  {
    SELECT ?riskTolerance (AVG(xsd:decimal(?totalCashFlow)) AS ?avgNetCashFlow)
    WHERE {
      ?inv rdf:type wm:Investor .
      ?inv wm:investorId ?investorId .
      ?inv wm:riskTolerance ?riskTolerance .
      {
        SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?totalCashFlow)
        WHERE {
          ?cf rdf:type wm:CashFlow .
          ?cf wm:investorId ?investorId .
          ?cf wm:amount ?cfAmount .
        }
        GROUP BY ?investorId
      }
    }
    GROUP BY ?riskTolerance
  }
  {
    SELECT ?riskTolerance (AVG(xsd:decimal(?cfAmount)) AS ?avgCashFlowAmount)
    WHERE {
      ?inv rdf:type wm:Investor .
      ?inv wm:investorId ?investorId .
      ?inv wm:riskTolerance ?riskTolerance .
      ?cf rdf:type wm:CashFlow .
      ?cf wm:investorId ?investorId .
      ?cf wm:amount ?cfAmount .
    }
    GROUP BY ?riskTolerance
  }
  {
    SELECT ?riskTolerance (AVG(xsd:decimal(?totalHoldingValue)) AS ?avgTotalHoldingValue)
    WHERE {
      ?inv rdf:type wm:Investor .
      ?inv wm:investorId ?investorId .
      ?inv wm:riskTolerance ?riskTolerance .
      {
        SELECT ?investorId (SUM(xsd:decimal(?holdingValue)) AS ?totalHoldingValue)
        WHERE {
          ?ph rdf:type wm:PortfolioHolding .
          ?ph wm:investorId ?investorId .
          ?ph wm:currentValue ?holdingValue .
        }
        GROUP BY ?investorId
      }
    }
    GROUP BY ?riskTolerance
  }
  {
    SELECT ?riskTolerance (AVG(xsd:decimal(?totalRebalanceAmount)) AS ?avgTotalRebalanceAmount)
    WHERE {
      ?inv rdf:type wm:Investor .
      ?inv wm:investorId ?investorId .
      ?inv wm:riskTolerance ?riskTolerance .
      {
        SELECT ?investorId (SUM(xsd:decimal(?rebAmount)) AS ?totalRebalanceAmount)
        WHERE {
          ?ra rdf:type wm:RebalancingAction .
          ?ra wm:investorId ?investorId .
          ?ra wm:amount ?rebAmount .
        }
        GROUP BY ?investorId
      }
    }
    GROUP BY ?riskTolerance
  }
  {
    SELECT ?riskTolerance (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore)
    WHERE {
      ?inv rdf:type wm:Investor .
      ?inv wm:investorId ?investorId .
      ?inv wm:riskTolerance ?riskTolerance .
      ?phl rdf:type wm:PortfolioHealth .
      ?phl wm:investorId ?investorId .
      ?phl wm:riskScore ?riskScore .
    }
    GROUP BY ?riskTolerance
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTol
       (AVG(xsd:decimal(?netCashFlow)) AS ?avgNetCashFlow)
       (AVG(xsd:decimal(?avgCashFlowAmt)) AS ?avgCashFlowAmount)
       (AVG(xsd:decimal(?totalHoldingValue)) AS ?avgTotalHoldingValue)
       (AVG(xsd:decimal(?avgShift)) AS ?avgScenarioAllocationShift)
       (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore)
WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:hasRiskTolerance ?rt .
  OPTIONAL { ?rt rdfs:label ?riskTol . }
  BIND(COALESCE(?riskTol, "UNKNOWN") AS ?riskTol)

  # Net cash flow per investor
  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?cfAmt)) AS ?netCashFlow)
    WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:hasCashFlowOfInvestor ?investor .
      ?cf wm:amount ?cfAmt .
    }
    GROUP BY ?investor
  }

  # Average cash‑flow amount per investor
  OPTIONAL {
    SELECT ?investor (AVG(xsd:decimal(?cfAmt2)) AS ?avgCashFlowAmt)
    WHERE {
      ?cf2 rdf:type wm:CashFlow .
      ?cf2 wm:hasCashFlowOfInvestor ?investor .
      ?cf2 wm:amount ?cfAmt2 .
    }
    GROUP BY ?investor
  }

  # Total holding value per investor
  OPTIONAL {
    SELECT ?investor (SUM(xsd:decimal(?holdVal)) AS ?totalHoldingValue)
    WHERE {
      ?ph rdf:type wm:PortfolioHolding .
      ?ph wm:heldByInvestor ?investor .
      ?ph wm:currentValue ?holdVal .
    }
    GROUP BY ?investor
  }

  # Average scenario allocation shift per investor
  OPTIONAL {
    SELECT ?investor (AVG(xsd:decimal(?shiftVal)) AS ?avgShift)
    WHERE {
      ?sr rdf:type wm:ScenarioRebalancing .
      ?sr wm:scenarioRebalancingOfInvestor ?investor .
      ?sr wm:newAllocationPct ?newPct .
      ?sr wm:currentAllocationPct ?curPct .
      BIND(xsd:decimal(?newPct) - xsd:decimal(?curPct) AS ?shiftVal)
    }
    GROUP BY ?investor
  }

  # Risk score per investor
  OPTIONAL {
    SELECT ?investor (AVG(xsd:decimal(?riskScoreVal)) AS ?riskScore)
    WHERE {
      ?phl rdf:type wm:PortfolioHealth .
      ?phl wm:healthOfInvestor ?investor .
      ?phl wm:riskScore ?riskScoreVal .
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTol

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (AVG(xsd:decimal(?totalCashFlow)) AS ?avgNetCashFlow)
       (AVG(xsd:decimal(?avgCashFlowAmount)) AS ?avgCashFlowAmount)
       (AVG(xsd:decimal(?totalRebalanceAmount)) AS ?avgTotalRebalanceAmount)
       (AVG(xsd:decimal(?totalSectorInvestment)) AS ?avgTotalSectorInvestment)
       (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore)
WHERE {
  ?inv rdf:type wm:Investor .
  ?inv wm:investorId ?investorId .
  ?inv wm:riskTolerance ?riskTolerance .

  OPTIONAL {
    {
      SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?totalCashFlow) (AVG(xsd:decimal(?cfAmount)) AS ?avgCashFlowAmount)
      WHERE {
        ?cf rdf:type wm:CashFlow .
        ?cf wm:investorId ?investorId .
        ?cf wm:amount ?cfAmount .
      }
      GROUP BY ?investorId
    }
  }

  OPTIONAL {
    {
      SELECT ?investorId (SUM(xsd:decimal(?rebAmount)) AS ?totalRebalanceAmount)
      WHERE {
        ?ra rdf:type wm:RebalancingAction .
        ?ra wm:investorId ?investorId .
        ?ra wm:amount ?rebAmount .
      }
      GROUP BY ?investorId
    }
  }

  OPTIONAL {
    {
      SELECT ?investorId (SUM(xsd:decimal(?totalInv)) AS ?totalSectorInvestment)
      WHERE {
        ?sa rdf:type wm:SectorAllocation .
        ?sa wm:investorId ?investorId .
        ?sa wm:totalInvestment ?totalInv .
      }
      GROUP BY ?investorId
    }
  }

  OPTIONAL {
    {
      SELECT ?investorId (xsd:decimal(?riskScore) AS ?riskScore)
      WHERE {
        ?ph rdf:type wm:PortfolioHealth .
        ?ph wm:investorId ?investorId .
        ?ph wm:riskScore ?riskScore .
      }
      GROUP BY ?investorId
    }
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskToleranceLabel
       (AVG(xsd:decimal(?totalCashFlow)) AS ?avgNetCashFlow)
       (AVG(xsd:decimal(?avgCashFlowAmount)) AS ?avgCashFlowAmount)
       (AVG(xsd:decimal(?totalRebalance)) AS ?avgTotalRebalanceAmount)
       (AVG(xsd:decimal(?totalSectorInvestment)) AS ?avgTotalSectorInvestment)
       (AVG(xsd:decimal(?avgGoalProgress)) AS ?avgGoalProgress)
WHERE {
  # Investor and risk tolerance
  ?investor rdf:type wm:Investor .
  ?investor wm:hasRiskTolerance ?rt .
  ?rt rdfs:label ?riskToleranceLabel .

  # Cash flow aggregates per investor
  {
    SELECT ?investor (SUM(xsd:decimal(?cfAmount)) AS ?totalCashFlow) (AVG(xsd:decimal(?cfAmount)) AS ?avgCashFlowAmount)
    WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?investor .
      ?cf wm:amount ?cfAmount .
    }
    GROUP BY ?investor
  }

  # Rebalancing aggregates per investor
  {
    SELECT ?investor (SUM(xsd:decimal(?raAmount)) AS ?totalRebalance)
    WHERE {
      ?ra rdf:type wm:RebalancingAction .
      ?ra wm:rebalancingActionOfInvestor ?investor .
      ?ra wm:amount ?raAmount .
    }
    GROUP BY ?investor
  }

  # Sector investment aggregates per investor
  {
    SELECT ?investor (SUM(xsd:decimal(?saTotal)) AS ?totalSectorInvestment)
    WHERE {
      ?sa rdf:type wm:SectorAllocation .
      ?sa wm:allocationOfInvestor ?investor .
      ?sa wm:totalInvestment ?saTotal .
    }
    GROUP BY ?investor
  }

  # Goal progress aggregates per investor
  {
    SELECT ?investor (AVG(xsd:decimal(?goalProgress)) AS ?avgGoalProgress)
    WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?investor .
      ?goal wm:progressPct ?goalProgress .
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskToleranceLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (AVG(xsd:decimal(?netCashFlow)) AS ?avgNetCashFlow)
       (AVG(xsd:decimal(?cashFlowAmt)) AS ?avgCashFlowAmount)
       (AVG(xsd:decimal(?totalRebalanceAmt)) AS ?avgTotalRebalanceAmount)
       (AVG(xsd:decimal(?totalSectorInv)) AS ?avgTotalSectorInvestment)
       (AVG(xsd:decimal(?allocShift)) AS ?avgScenarioAllocationShift)
WHERE {
  ?investor rdf:type wm:Investor .
  OPTIONAL { ?investor wm:riskTolerance ?rt . }
  BIND (COALESCE(?rt, "NULL") AS ?riskTolerance)

  # Net cash flow per investor
  {
    SELECT ?investor (SUM(xsd:decimal(?cfAmt)) AS ?netCashFlow) WHERE {
      ?investor wm:hasCashFlow ?cf .
      ?cf rdf:type wm:CashFlow .
      ?cf wm:amount ?cfAmt .
    } GROUP BY ?investor
  }

  # Individual cash‑flow amounts for average cash‑flow amount
  OPTIONAL {
    ?investor wm:hasCashFlow ?cf2 .
    ?cf2 rdf:type wm:CashFlow .
    ?cf2 wm:amount ?cashFlowAmt .
  }

  # Total rebalance amount per investor
  {
    SELECT ?investor (SUM(xsd:decimal(?rebAmt)) AS ?totalRebalanceAmt) WHERE {
      ?investor wm:hasRebalancingAction ?reb .
      ?reb rdf:type wm:RebalancingAction .
      ?reb wm:amount ?rebAmt .
    } GROUP BY ?investor
  }

  # Total sector investment per investor
  {
    SELECT ?investor (SUM(xsd:decimal(?sectorInv)) AS ?totalSectorInv) WHERE {
      ?investor wm:hasSectorAllocation ?sa .
      ?sa rdf:type wm:SectorAllocation .
      ?sa wm:totalInvestment ?sectorInv .
    } GROUP BY ?investor
  }

  # Scenario allocation shift (new minus current)
  OPTIONAL {
    ?investor wm:hasScenarioRebalancing ?sr .
    ?sr rdf:type wm:ScenarioRebalancing .
    ?sr wm:newAllocationPct ?newPct .
    ?sr wm:currentAllocationPct ?curPct .
    BIND ((xsd:decimal(?newPct) - xsd:decimal(?curPct)) AS ?allocShift)
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?compositeScore WHERE {
  # per‑investor aggregates
  {
    SELECT ?investorId ?cashFlowSum ?holdingGain ?rebalanceSum ?scenarioShift WHERE {
      {
        SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?cashFlowSum) WHERE {
          ?cf rdf:type wm:CashFlow .
          ?cf wm:investorId ?investorId .
          ?cf wm:amount ?cfAmount .
        } GROUP BY ?investorId
      }
      {
        SELECT ?investorId (SUM(xsd:decimal(?gain)) AS ?holdingGain) WHERE {
          ?ph rdf:type wm:PortfolioHolding .
          ?ph wm:investorId ?investorId .
          ?ph wm:cost ?cost .
          ?ph wm:currentValue ?cur .
          BIND((xsd:decimal(?cur) - xsd:decimal(?cost)) AS ?gain)
        } GROUP BY ?investorId
      }
      {
        SELECT ?investorId (SUM(xsd:decimal(?raAmount)) AS ?rebalanceSum) WHERE {
          ?ra rdf:type wm:RebalancingAction .
          ?ra wm:investorId ?investorId .
          ?ra wm:amount ?raAmount .
        } GROUP BY ?investorId
      }
      {
        SELECT ?investorId (SUM(xsd:decimal(?shift)) AS ?scenarioShift) WHERE {
          ?sr rdf:type wm:ScenarioRebalancing .
          ?sr wm:investorId ?investorId .
          ?sr wm:newAllocationPct ?new .
          ?sr wm:currentAllocationPct ?curAlloc .
          BIND((xsd:decimal(?new) - xsd:decimal(?curAlloc)) AS ?shift)
        } GROUP BY ?investorId
      }
    }
  }
  FILTER(bound(?cashFlowSum) && bound(?holdingGain) && bound(?rebalanceSum) && bound(?scenarioShift))

  # min / max for cash flow
  {
    SELECT (MIN(?cfs) AS ?minCash) (MAX(?cfs) AS ?maxCash) WHERE {
      {
        SELECT ?inv (SUM(xsd:decimal(?amt)) AS ?cfs) WHERE {
          ?cf2 rdf:type wm:CashFlow .
          ?cf2 wm:investorId ?inv .
          ?cf2 wm:amount ?amt .
        } GROUP BY ?inv
      }
    }
  }
  # min / max for holding gain
  {
    SELECT (MIN(?hg) AS ?minHolding) (MAX(?hg) AS ?maxHolding) WHERE {
      {
        SELECT ?inv (SUM(xsd:decimal(?gain2)) AS ?hg) WHERE {
          ?ph2 rdf:type wm:PortfolioHolding .
          ?ph2 wm:investorId ?inv .
          ?ph2 wm:cost ?c2 .
          ?ph2 wm:currentValue ?v2 .
          BIND((xsd:decimal(?v2) - xsd:decimal(?c2)) AS ?gain2)
        } GROUP BY ?inv
      }
    }
  }
  # min / max for rebalance amount
  {
    SELECT (MIN(?ras) AS ?minRebalance) (MAX(?ras) AS ?maxRebalance) WHERE {
      {
        SELECT ?inv (SUM(xsd:decimal(?amt2)) AS ?ras) WHERE {
          ?ra2 rdf:type wm:RebalancingAction .
          ?ra2 wm:investorId ?inv .
          ?ra2 wm:amount ?amt2 .
        } GROUP BY ?inv
      }
    }
  }
  # min / max for scenario shift
  {
    SELECT (MIN(?ss) AS ?minScenario) (MAX(?ss) AS ?maxScenario) WHERE {
      {
        SELECT ?inv (SUM(xsd:decimal(?shift2)) AS ?ss) WHERE {
          ?sr2 rdf:type wm:ScenarioRebalancing .
          ?sr2 wm:investorId ?inv .
          ?sr2 wm:newAllocationPct ?new2 .
          ?sr2 wm:currentAllocationPct ?cur2 .
          BIND((xsd:decimal(?new2) - xsd:decimal(?cur2)) AS ?shift2)
        } GROUP BY ?inv
      }
    }
  }

  # normalise each component
  BIND( IF(?maxCash = ?minCash, 0, (xsd:decimal(?cashFlowSum) - ?minCash) / (?maxCash - ?minCash)) AS ?normCash )
  BIND( IF(?maxHolding = ?minHolding, 0, (xsd:decimal(?holdingGain) - ?minHolding) / (?maxHolding - ?minHolding)) AS ?normHolding )
  BIND( IF(?maxRebalance = ?minRebalance, 0, (xsd:decimal(?rebalanceSum) - ?minRebalance) / (?maxRebalance - ?minRebalance)) AS ?normRebalance )
  BIND( IF(?maxScenario = ?minScenario, 0, (xsd:decimal(?scenarioShift) - ?minScenario) / (?maxScenario - ?minScenario)) AS ?normScenario )

  BIND( ( ( ?normCash + ?normHolding + ?normRebalance + ?normScenario ) / 4 ) * 100 AS ?compositeScore )
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?compositeScore WHERE {
  ?inv rdf:type wm:Investor .
  ?inv wm:investorId ?investorId .

  {
    SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?totalCashFlow) WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:investorId ?investorId .
      ?cf wm:amount ?cfAmount .
    } GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?gain)) AS ?totalHoldingGain) WHERE {
      ?h rdf:type wm:PortfolioHolding .
      ?h wm:investorId ?investorId .
      ?h wm:cost ?cost .
      ?h wm:currentValue ?curr .
      BIND(xsd:decimal(?curr) - xsd:decimal(?cost) AS ?gain)
    } GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?raAmount)) AS ?totalRebalance) WHERE {
      ?ra rdf:type wm:RebalancingAction .
      ?ra wm:investorId ?investorId .
      ?ra wm:amount ?raAmount .
    } GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SUM(xsd:decimal(?totalInv)) AS ?totalSectorInv) WHERE {
      ?sa rdf:type wm:SectorAllocation .
      ?sa wm:investorId ?investorId .
      ?sa wm:totalInvestment ?totalInv .
    } GROUP BY ?investorId
  }

  BIND( (xsd:decimal(?totalCashFlow) + xsd:decimal(?totalHoldingGain) + xsd:decimal(?totalRebalance) + xsd:decimal(?totalSectorInv)) AS ?compositeScore )
}
ORDER BY DESC(?compositeScore) ASC(?investorId)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ( (?netCashFlow + ?totalHoldingGain + ?totalRebalanceAmount - ?avgGoalShortfall) AS ?compositeScore )
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlow)
    WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:investorId ?investorId .
      ?cf wm:amount ?cfAmount .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?gain)) AS ?totalHoldingGain)
    WHERE {
      ?h rdf:type wm:PortfolioHolding .
      ?h wm:investorId ?investorId .
      ?h wm:cost ?cost .
      ?h wm:currentValue ?curr .
      BIND( (xsd:decimal(?curr) - xsd:decimal(?cost)) AS ?gain )
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?rebAmount)) AS ?totalRebalanceAmount)
    WHERE {
      ?ra rdf:type wm:RebalancingAction .
      ?ra wm:investorId ?investorId .
      ?ra wm:amount ?rebAmount .
    }
    GROUP BY ?investorId
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?shortfall)) AS ?avgGoalShortfall)
    WHERE {
      ?g rdf:type wm:InvestmentGoal .
      ?g wm:investorId ?investorId .
      ?g wm:shortfall ?shortfall .
    }
    GROUP BY ?investorId
  }
  ?inv rdf:type wm:Investor .
  ?inv wm:investorId ?investorId .
}
ORDER BY DESC(?compositeScore) ASC(?investorId)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?compositeScore
WHERE {
  # Net cash flow per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlow)
    WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:investorId ?investorId .
      ?cf wm:amount ?cfAmount .
    }
    GROUP BY ?investorId
  }
  # Total holding gain per investor (only holdings with cost and currentValue)
  {
    SELECT ?investorId (SUM(xsd:decimal(?gain)) AS ?totalHoldingGain)
    WHERE {
      ?h rdf:type wm:PortfolioHolding .
      ?h wm:investorId ?investorId .
      ?h wm:cost ?cost .
      ?h wm:currentValue ?curr .
      BIND( (xsd:decimal(?curr) - xsd:decimal(?cost)) AS ?gain )
    }
    GROUP BY ?investorId
  }
  # Total sector investment per investor
  {
    SELECT ?investorId (SUM(xsd:decimal(?totalInv)) AS ?totalSectorInvestment)
    WHERE {
      ?sa rdf:type wm:SectorAllocation .
      ?sa wm:investorId ?investorId .
      ?sa wm:totalInvestment ?totalInv .
    }
    GROUP BY ?investorId
  }
  # Average goal shortfall per investor
  {
    SELECT ?investorId (AVG(xsd:decimal(?shortfall)) AS ?avgGoalShortfall)
    WHERE {
      ?g rdf:type wm:InvestmentGoal .
      ?g wm:investorId ?investorId .
      ?g wm:shortfall ?shortfall .
    }
    GROUP BY ?investorId
  }
  # Ensure investor entity exists
  ?inv rdf:type wm:Investor .
  ?inv wm:investorId ?investorId .

  # Compute composite score
  BIND( (xsd:decimal(?netCashFlow) + xsd:decimal(?totalHoldingGain) + xsd:decimal(?totalSectorInvestment) - xsd:decimal(?avgGoalShortfall)) AS ?compositeScore )
}
ORDER BY DESC(?compositeScore) ASC(?investorId)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?compositeScore WHERE {
  ?inv rdf:type wm:Investor .
  ?inv wm:investorId ?investorId .

  {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cashFlowTotal) WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:investorId ?investorId .
      ?cf wm:amount ?amount .
    } GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?gain)) AS ?holdingGainTotal) WHERE {
      ?ph rdf:type wm:PortfolioHolding .
      ?ph wm:investorId ?investorId .
      ?ph wm:cost ?cost .
      ?ph wm:currentValue ?curr .
      FILTER(bound(?cost) && bound(?curr))
      BIND((xsd:decimal(?curr) - xsd:decimal(?cost)) AS ?gain)
    } GROUP BY ?investorId
  }
  {
    SELECT ?investorId (SUM(xsd:decimal(?shift)) AS ?scenarioShiftTotal) WHERE {
      ?sr rdf:type wm:ScenarioRebalancing .
      ?sr wm:investorId ?investorId .
      ?sr wm:newAllocationPct ?new .
      ?sr wm:currentAllocationPct ?cur .
      BIND((xsd:decimal(?new) - xsd:decimal(?cur)) AS ?shift)
    } GROUP BY ?investorId
  }
  {
    SELECT ?investorId (MAX(xsd:decimal(?riskScore)) AS ?riskScore) WHERE {
      ?phs rdf:type wm:PortfolioHealth .
      ?phs wm:investorId ?investorId .
      ?phs wm:riskScore ?riskScore .
    } GROUP BY ?investorId
  }

  {
    SELECT (MIN(?cfTot) AS ?minCash) (MAX(?cfTot) AS ?maxCash)
           (MIN(?gainTot) AS ?minGain) (MAX(?gainTot) AS ?maxGain)
           (MIN(?shiftTot) AS ?minShift) (MAX(?shiftTot) AS ?maxShift)
           (MIN(?risk) AS ?minRisk) (MAX(?risk) AS ?maxRisk) WHERE {
      {
        SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cfTot) WHERE {
          ?cf rdf:type wm:CashFlow .
          ?cf wm:investorId ?investorId .
          ?cf wm:amount ?amount .
        } GROUP BY ?investorId
      }
      {
        SELECT ?investorId (SUM(xsd:decimal(?gain)) AS ?gainTot) WHERE {
          ?ph rdf:type wm:PortfolioHolding .
          ?ph wm:investorId ?investorId .
          ?ph wm:cost ?cost .
          ?ph wm:currentValue ?curr .
          FILTER(bound(?cost) && bound(?curr))
          BIND((xsd:decimal(?curr) - xsd:decimal(?cost)) AS ?gain)
        } GROUP BY ?investorId
      }
      {
        SELECT ?investorId (SUM(xsd:decimal(?shift)) AS ?shiftTot) WHERE {
          ?sr rdf:type wm:ScenarioRebalancing .
          ?sr wm:investorId ?investorId .
          ?sr wm:newAllocationPct ?new .
          ?sr wm:currentAllocationPct ?cur .
          BIND((xsd:decimal(?new) - xsd:decimal(?cur)) AS ?shift)
        } GROUP BY ?investorId
      }
      {
        SELECT ?investorId (MAX(xsd:decimal(?riskScore)) AS ?risk) WHERE {
          ?phs rdf:type wm:PortfolioHealth .
          ?phs wm:investorId ?investorId .
          ?phs wm:riskScore ?riskScore .
        } GROUP BY ?investorId
      }
    }
  }

  BIND( IF(?maxCash = ?minCash, 0, ((?cashFlowTotal - ?minCash) / (?maxCash - ?minCash))) AS ?normCash )
  BIND( IF(?maxGain = ?minGain, 0, ((?holdingGainTotal - ?minGain) / (?maxGain - ?minGain))) AS ?normGain )
  BIND( IF(?maxShift = ?minShift, 0, ((?scenarioShiftTotal - ?minShift) / (?maxShift - ?minShift))) AS ?normShift )
  BIND( IF(?maxRisk = ?minRisk, 0, ((?riskScore - ?minRisk) / (?maxRisk - ?minRisk))) AS ?normRisk )
  BIND( ((?normCash + ?normGain + ?normShift + ?normRisk) / 4) * 100 AS ?compositeScore )
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?compositeScore WHERE {
  {
    SELECT ?investorId ?totalCashFlow ?totalRebalance ?totalSectorInv ?totalScenarioShift
    WHERE {
      {
        SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?totalCashFlow)
        WHERE {
          ?cf rdf:type wm:CashFlow .
          ?cf wm:investorId ?investorId .
          ?cf wm:amount ?cfAmount .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId (SUM(xsd:decimal(?rebAmount)) AS ?totalRebalance)
        WHERE {
          ?ra rdf:type wm:RebalancingAction .
          ?ra wm:investorId ?investorId .
          ?ra wm:amount ?rebAmount .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId (SUM(xsd:decimal(?sectorInv)) AS ?totalSectorInv)
        WHERE {
          ?sa rdf:type wm:SectorAllocation .
          ?sa wm:investorId ?investorId .
          ?sa wm:totalInvestment ?sectorInv .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId (SUM(xsd:decimal(?shiftAmt)) AS ?totalScenarioShift)
        WHERE {
          ?sr rdf:type wm:ScenarioRebalancing .
          ?sr wm:investorId ?investorId .
          ?sr wm:newAllocationPct ?newPct .
          ?sr wm:currentAllocationPct ?curPct .
          BIND(xsd:decimal(?newPct) - xsd:decimal(?curPct) AS ?shiftAmt)
        }
        GROUP BY ?investorId
      }
    }
  }
  {
    SELECT (MIN(?totalCashFlow) AS ?minCash) (MAX(?totalCashFlow) AS ?maxCash)
           (MIN(?totalRebalance) AS ?minReb) (MAX(?totalRebalance) AS ?maxReb)
           (MIN(?totalSectorInv) AS ?minSector) (MAX(?totalSectorInv) AS ?maxSector)
           (MIN(?totalScenarioShift) AS ?minShift) (MAX(?totalScenarioShift) AS ?maxShift)
    WHERE {
      {
        SELECT ?investorId ?totalCashFlow ?totalRebalance ?totalSectorInv ?totalScenarioShift
        WHERE {
          {
            SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?totalCashFlow)
            WHERE {
              ?cf rdf:type wm:CashFlow .
              ?cf wm:investorId ?investorId .
              ?cf wm:amount ?cfAmount .
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId (SUM(xsd:decimal(?rebAmount)) AS ?totalRebalance)
            WHERE {
              ?ra rdf:type wm:RebalancingAction .
              ?ra wm:investorId ?investorId .
              ?ra wm:amount ?rebAmount .
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId (SUM(xsd:decimal(?sectorInv)) AS ?totalSectorInv)
            WHERE {
              ?sa rdf:type wm:SectorAllocation .
              ?sa wm:investorId ?investorId .
              ?sa wm:totalInvestment ?sectorInv .
            }
            GROUP BY ?investorId
          }
          {
            SELECT ?investorId (SUM(xsd:decimal(?shiftAmt)) AS ?totalScenarioShift)
            WHERE {
              ?sr rdf:type wm:ScenarioRebalancing .
              ?sr wm:investorId ?investorId .
              ?sr wm:newAllocationPct ?newPct .
              ?sr wm:currentAllocationPct ?curPct .
              BIND(xsd:decimal(?newPct) - xsd:decimal(?curPct) AS ?shiftAmt)
            }
            GROUP BY ?investorId
          }
        }
      }
    }
  }
  BIND( IF(?maxCash = ?minCash, 0, (xsd:decimal(?totalCashFlow) - ?minCash) / (?maxCash - ?minCash)) AS ?normCash )
  BIND( IF(?maxReb = ?minReb, 0, (xsd:decimal(?totalRebalance) - ?minReb) / (?maxReb - ?minReb)) AS ?normReb )
  BIND( IF(?maxSector = ?minSector, 0, (xsd:decimal(?totalSectorInv) - ?minSector) / (?maxSector - ?minSector)) AS ?normSector )
  BIND( IF(?maxShift = ?minShift, 0, (xsd:decimal(?totalScenarioShift) - ?minShift) / (?maxShift - ?minShift)) AS ?normShift )
  BIND( ((?normCash + ?normReb + ?normSector + ?normShift) / 4) * 100 AS ?compositeScore )
}
ORDER BY DESC(?compositeScore) ASC(?investorId)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?compositeScore WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlow) (SUM(xsd:decimal(?rebAmount)) AS ?totalRebalance) (SUM(xsd:decimal(?sectorInv)) AS ?totalSectorInv) ?riskScore WHERE {
      OPTIONAL {
        ?cf rdf:type wm:CashFlow .
        ?cf wm:investorId ?investorId .
        ?cf wm:amount ?cfAmount .
      }
      OPTIONAL {
        ?ra rdf:type wm:RebalancingAction .
        ?ra wm:investorId ?investorId .
        ?ra wm:amount ?rebAmount .
      }
      OPTIONAL {
        ?sa rdf:type wm:SectorAllocation .
        ?sa wm:investorId ?investorId .
        ?sa wm:totalInvestment ?sectorInv .
      }
      ?ph rdf:type wm:PortfolioHealth .
      ?ph wm:investorId ?investorId .
      ?ph wm:riskScore ?riskScore .
    }
    GROUP BY ?investorId ?riskScore
    HAVING (BOUND(?netCashFlow) && BOUND(?totalRebalance) && BOUND(?totalSectorInv) && BOUND(?riskScore))
  }
  {
    SELECT (MIN(?netCashFlow) AS ?minCash) (MAX(?netCashFlow) AS ?maxCash)
           (MIN(?totalRebalance) AS ?minReb) (MAX(?totalRebalance) AS ?maxReb)
           (MIN(?totalSectorInv) AS ?minSector) (MAX(?totalSectorInv) AS ?maxSector)
           (MIN(?riskScore) AS ?minRisk) (MAX(?riskScore) AS ?maxRisk) WHERE {
      {
        SELECT ?investorId (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlow) (SUM(xsd:decimal(?rebAmount)) AS ?totalRebalance) (SUM(xsd:decimal(?sectorInv)) AS ?totalSectorInv) ?riskScore WHERE {
          OPTIONAL {
            ?cf rdf:type wm:CashFlow .
            ?cf wm:investorId ?investorId .
            ?cf wm:amount ?cfAmount .
          }
          OPTIONAL {
            ?ra rdf:type wm:RebalancingAction .
            ?ra wm:investorId ?investorId .
            ?ra wm:amount ?rebAmount .
          }
          OPTIONAL {
            ?sa rdf:type wm:SectorAllocation .
            ?sa wm:investorId ?investorId .
            ?sa wm:totalInvestment ?sectorInv .
          }
          ?ph rdf:type wm:PortfolioHealth .
          ?ph wm:investorId ?investorId .
          ?ph wm:riskScore ?riskScore .
        }
        GROUP BY ?investorId ?riskScore
        HAVING (BOUND(?netCashFlow) && BOUND(?totalRebalance) && BOUND(?totalSectorInv) && BOUND(?riskScore))
      }
    }
  }
  BIND( IF(?maxCash != ?minCash, (xsd:decimal(?netCashFlow) - xsd:decimal(?minCash)) / (xsd:decimal(?maxCash) - xsd:decimal(?minCash)), 0) AS ?normCash )
  BIND( IF(?maxReb != ?minReb, (xsd:decimal(?totalRebalance) - xsd:decimal(?minReb)) / (xsd:decimal(?maxReb) - xsd:decimal(?minReb)), 0) AS ?normReb )
  BIND( IF(?maxSector != ?minSector, (xsd:decimal(?totalSectorInv) - xsd:decimal(?minSector)) / (xsd:decimal(?maxSector) - xsd:decimal(?minSector)), 0) AS ?normSector )
  BIND( IF(?maxRisk != ?minRisk, (xsd:decimal(?riskScore) - xsd:decimal(?minRisk)) / (xsd:decimal(?maxRisk) - xsd:decimal(?minRisk)), 0) AS ?normRisk )
  BIND( ((?normCash + ?normReb + ?normSector + ?normRisk) / 4) * 100 AS ?compositeScore )
}
ORDER BY DESC(?compositeScore) ASC(?investorId)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?compositeScore WHERE {
  {
    SELECT ?investorId ?cashFlow ?holdingGain ?riskScore ?avgShortfall WHERE {
      {
        SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cashFlow) WHERE {
          ?cf rdf:type wm:CashFlow .
          ?cf wm:amount ?amount .
          ?cf wm:investorId ?investorId .
        } GROUP BY ?investorId
      }
      {
        SELECT ?investorId (SUM(xsd:decimal(?gain)) AS ?holdingGain) WHERE {
          ?h rdf:type wm:PortfolioHolding .
          ?h wm:investorId ?investorId .
          ?h wm:cost ?cost .
          ?h wm:currentValue ?currentValue .
          BIND(xsd:decimal(?currentValue) - xsd:decimal(?cost) AS ?gain)
        } GROUP BY ?investorId
      }
      {
        SELECT ?investorId ?riskScore WHERE {
          ?ph rdf:type wm:PortfolioHealth .
          ?ph wm:riskScore ?riskScore .
          ?ph wm:investorId ?investorId .
        }
      }
      {
        SELECT ?investorId (AVG(xsd:decimal(?shortfall)) AS ?avgShortfall) WHERE {
          ?g rdf:type wm:InvestmentGoal .
          ?g wm:shortfall ?shortfall .
          ?g wm:investorId ?investorId .
        } GROUP BY ?investorId
      }
    }
  }
  FILTER(BOUND(?cashFlow) && BOUND(?holdingGain) && BOUND(?riskScore) && BOUND(?avgShortfall))
  {
    SELECT (MIN(?c) AS ?minCash) (MAX(?c) AS ?maxCash)
           (MIN(?g) AS ?minGain) (MAX(?g) AS ?maxGain)
           (MIN(?r) AS ?minRisk) (MAX(?r) AS ?maxRisk)
           (MIN(?s) AS ?minShort) (MAX(?s) AS ?maxShort) WHERE {
      {
        SELECT ?investorId (SUM(xsd:decimal(?amount2)) AS ?c) WHERE {
          ?cf2 rdf:type wm:CashFlow .
          ?cf2 wm:amount ?amount2 .
          ?cf2 wm:investorId ?investorId .
        } GROUP BY ?investorId
      }
      {
        SELECT ?investorId (SUM(xsd:decimal(?gain2)) AS ?g) WHERE {
          ?h2 rdf:type wm:PortfolioHolding .
          ?h2 wm:investorId ?investorId .
          ?h2 wm:cost ?cost2 .
          ?h2 wm:currentValue ?currentValue2 .
          BIND(xsd:decimal(?currentValue2) - xsd:decimal(?cost2) AS ?gain2)
        } GROUP BY ?investorId
      }
      {
        SELECT ?investorId ?r WHERE {
          ?ph2 rdf:type wm:PortfolioHealth .
          ?ph2 wm:riskScore ?r .
          ?ph2 wm:investorId ?investorId .
        }
      }
      {
        SELECT ?investorId (AVG(xsd:decimal(?shortfall2)) AS ?s) WHERE {
          ?g2 rdf:type wm:InvestmentGoal .
          ?g2 wm:shortfall ?shortfall2 .
          ?g2 wm:investorId ?investorId .
        } GROUP BY ?investorId
      }
      FILTER(BOUND(?c) && BOUND(?g) && BOUND(?r) && BOUND(?s))
    }
  }
  BIND(IF(?maxCash = ?minCash, 0, (xsd:decimal(?cashFlow) - ?minCash) / (?maxCash - ?minCash)) AS ?normCash)
  BIND(IF(?maxGain = ?minGain, 0, (xsd:decimal(?holdingGain) - ?minGain) / (?maxGain - ?minGain)) AS ?normGain)
  BIND(IF(?maxRisk = ?minRisk, 0, (xsd:decimal(?riskScore) - ?minRisk) / (?maxRisk - ?minRisk)) AS ?normRisk)
  BIND(IF(?maxShort = ?minShort, 0, (xsd:decimal(?avgShortfall) - ?minShort) / (?maxShort - ?minShort)) AS ?normShort)
  BIND((1 - ?normShort) AS ?normShortInv)
  BIND(((?normCash + ?normGain + ?normRisk + ?normShortInv) / 4) * 100 AS ?compositeScore)
}
ORDER BY DESC(?compositeScore) ASC(?investorId)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?compositeScore WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .

  {
    SELECT ?investor (SUM(xsd:decimal(?cfAmount)) AS ?netCashFlow) WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:amount ?cfAmount .
      ?cf wm:cashFlowOfInvestor ?investor .
    } GROUP BY ?investor
  }
  {
    SELECT ?investor (SUM(xsd:decimal(?rebAmount)) AS ?totalRebalance) WHERE {
      ?reb rdf:type wm:RebalancingAction .
      ?reb wm:amount ?rebAmount .
      ?reb wm:rebalancingActionOfInvestor ?investor .
    } GROUP BY ?investor
  }
  {
    SELECT ?investor (SUM(xsd:decimal(?sectorInv)) AS ?totalSectorInvestment) WHERE {
      ?sa rdf:type wm:SectorAllocation .
      ?sa wm:totalInvestment ?sectorInv .
      ?sa wm:allocationOfInvestor ?investor .
    } GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?shortfall)) AS ?avgGoalShortfall) WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:shortfall ?shortfall .
      ?goal wm:belongsToInvestor ?investor .
    } GROUP BY ?investor
  }

  BIND( (xsd:decimal(?netCashFlow) + xsd:decimal(?totalRebalance) + xsd:decimal(?totalSectorInvestment) - xsd:decimal(?avgGoalShortfall)) AS ?compositeScore )
}
ORDER BY DESC(?compositeScore) ASC(?investorId)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?compositeScore WHERE {
  {
    SELECT ?investorId ?cashFlowSum ?rebalanceSum ?scenarioShiftSum ?riskScoreVal
    WHERE {
      {
        SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cashFlowSum)
        WHERE {
          ?cf rdf:type wm:CashFlow .
          ?cf wm:investorId ?investorId .
          ?cf wm:amount ?amount .
        } GROUP BY ?investorId
      }
      {
        SELECT ?investorId (SUM(xsd:decimal(?raAmount)) AS ?rebalanceSum)
        WHERE {
          ?ra rdf:type wm:RebalancingAction .
          ?ra wm:investorId ?investorId .
          ?ra wm:amount ?raAmount .
        } GROUP BY ?investorId
      }
      {
        SELECT ?investorId (SUM(xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc)) AS ?scenarioShiftSum)
        WHERE {
          ?sr rdf:type wm:ScenarioRebalancing .
          ?sr wm:investorId ?investorId .
          ?sr wm:newAllocationPct ?newAlloc .
          ?sr wm:currentAllocationPct ?currAlloc .
        } GROUP BY ?investorId
      }
      {
        SELECT ?investorId (xsd:decimal(?riskScore) AS ?riskScoreVal)
        WHERE {
          ?ph rdf:type wm:PortfolioHealth .
          ?ph wm:investorId ?investorId .
          ?ph wm:riskScore ?riskScore .
        } GROUP BY ?investorId
      }
    }
  }
  {
    SELECT (MIN(?cashFlowSum) AS ?cashFlowMin) (MAX(?cashFlowSum) AS ?cashFlowMax)
           (MIN(?rebalanceSum) AS ?rebalanceMin) (MAX(?rebalanceSum) AS ?rebalanceMax)
           (MIN(?scenarioShiftSum) AS ?scenarioMin) (MAX(?scenarioShiftSum) AS ?scenarioMax)
           (MIN(?riskScoreVal) AS ?riskMin) (MAX(?riskScoreVal) AS ?riskMax)
    WHERE {
      {
        SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cashFlowSum)
        WHERE {
          ?cf rdf:type wm:CashFlow .
          ?cf wm:investorId ?investorId .
          ?cf wm:amount ?amount .
        } GROUP BY ?investorId
      }
      {
        SELECT ?investorId (SUM(xsd:decimal(?raAmount)) AS ?rebalanceSum)
        WHERE {
          ?ra rdf:type wm:RebalancingAction .
          ?ra wm:investorId ?investorId .
          ?ra wm:amount ?raAmount .
        } GROUP BY ?investorId
      }
      {
        SELECT ?investorId (SUM(xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc)) AS ?scenarioShiftSum)
        WHERE {
          ?sr rdf:type wm:ScenarioRebalancing .
          ?sr wm:investorId ?investorId .
          ?sr wm:newAllocationPct ?newAlloc .
          ?sr wm:currentAllocationPct ?currAlloc .
        } GROUP BY ?investorId
      }
      {
        SELECT ?investorId (xsd:decimal(?riskScore) AS ?riskScoreVal)
        WHERE {
          ?ph rdf:type wm:PortfolioHealth .
          ?ph wm:investorId ?investorId .
          ?ph wm:riskScore ?riskScore .
        } GROUP BY ?investorId
      }
    }
  }
  BIND( IF(?cashFlowMax = ?cashFlowMin, 0, (xsd:decimal(?cashFlowSum) - ?cashFlowMin) / (?cashFlowMax - ?cashFlowMin)) AS ?normCash )
  BIND( IF(?rebalanceMax = ?rebalanceMin, 0, (xsd:decimal(?rebalanceSum) - ?rebalanceMin) / (?rebalanceMax - ?rebalanceMin)) AS ?normReb )
  BIND( IF(?scenarioMax = ?scenarioMin, 0, (xsd:decimal(?scenarioShiftSum) - ?scenarioMin) / (?scenarioMax - ?scenarioMin)) AS ?normScenario )
  BIND( IF(?riskMax = ?riskMin, 0, (xsd:decimal(?riskScoreVal) - ?riskMin) / (?riskMax - ?riskMin)) AS ?normRisk )
  BIND( ((?normCash + ?normReb + ?normScenario + ?normRisk) / 4) * 100 AS ?compositeScore )
}
ORDER BY DESC(?compositeScore) ASC(?investorId)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?compositeScore
WHERE {
  {
    SELECT ?investorId ?cashFlowSum ?sectorInvSum ?scenarioShiftSum ?riskScore
    WHERE {
      {
        SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cashFlowSum)
        WHERE {
          ?cf rdf:type wm:CashFlow .
          ?cf wm:amount ?amount .
          ?cf wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId (SUM(xsd:decimal(?totalInv)) AS ?sectorInvSum)
        WHERE {
          ?sa rdf:type wm:SectorAllocation .
          ?sa wm:totalInvestment ?totalInv .
          ?sa wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId (SUM(xsd:decimal(?shift)) AS ?scenarioShiftSum)
        WHERE {
          ?sr rdf:type wm:ScenarioRebalancing .
          ?sr wm:newAllocationPct ?new .
          ?sr wm:currentAllocationPct ?cur .
          ?sr wm:investorId ?investorId .
          BIND ((xsd:decimal(?new) - xsd:decimal(?cur)) AS ?shift)
        }
        GROUP BY ?investorId
      }
      {
        SELECT ?investorId (MAX(xsd:decimal(?riskScore)) AS ?riskScore)
        WHERE {
          ?ph rdf:type wm:PortfolioHealth .
          ?ph wm:riskScore ?riskScore .
          ?ph wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
    }
  }
  {
    SELECT (MIN(?cash) AS ?minCash) (MAX(?cash) AS ?maxCash)
    WHERE {
      {
        SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cash)
        WHERE {
          ?cf rdf:type wm:CashFlow .
          ?cf wm:amount ?amount .
          ?cf wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
    }
  }
  {
    SELECT (MIN(?sec) AS ?minSector) (MAX(?sec) AS ?maxSector)
    WHERE {
      {
        SELECT ?investorId (SUM(xsd:decimal(?totalInv)) AS ?sec)
        WHERE {
          ?sa rdf:type wm:SectorAllocation .
          ?sa wm:totalInvestment ?totalInv .
          ?sa wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
    }
  }
  {
    SELECT (MIN(?sc) AS ?minScenario) (MAX(?sc) AS ?maxScenario)
    WHERE {
      {
        SELECT ?investorId (SUM(xsd:decimal(?shift)) AS ?sc)
        WHERE {
          ?sr rdf:type wm:ScenarioRebalancing .
          ?sr wm:newAllocationPct ?new .
          ?sr wm:currentAllocationPct ?cur .
          ?sr wm:investorId ?investorId .
          BIND ((xsd:decimal(?new) - xsd:decimal(?cur)) AS ?shift)
        }
        GROUP BY ?investorId
      }
    }
  }
  {
    SELECT (MIN(?rs) AS ?minRisk) (MAX(?rs) AS ?maxRisk)
    WHERE {
      {
        SELECT ?investorId (MAX(xsd:decimal(?riskScore)) AS ?rs)
        WHERE {
          ?ph rdf:type wm:PortfolioHealth .
          ?ph wm:riskScore ?riskScore .
          ?ph wm:investorId ?investorId .
        }
        GROUP BY ?investorId
      }
    }
  }
  BIND( IF(?maxCash = ?minCash, 0, (xsd:decimal(?cashFlowSum) - ?minCash) / (?maxCash - ?minCash)) AS ?normCash )
  BIND( IF(?maxSector = ?minSector, 0, (xsd:decimal(?sectorInvSum) - ?minSector) / (?maxSector - ?minSector)) AS ?normSector )
  BIND( IF(?maxScenario = ?minScenario, 0, (xsd:decimal(?scenarioShiftSum) - ?minScenario) / (?maxScenario - ?minScenario)) AS ?normScenario )
  BIND( IF(?maxRisk = ?minRisk, 0, (xsd:decimal(?riskScore) - ?minRisk) / (?maxRisk - ?minRisk)) AS ?normRisk )
  BIND( ((?normCash + ?normSector + ?normScenario + ?normRisk) / 4) * 100 AS ?compositeScore )
}
ORDER BY DESC(?compositeScore) ASC(?investorId)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?compositeScore WHERE {
  # per‑investor aggregates
  {
    SELECT ?investorId
           (SUM(xsd:decimal(?cfAmount)) AS ?totalCashFlow)
           (SUM(xsd:decimal(?gain)) AS ?totalHoldingGain)
           (SUM(xsd:decimal(?rebAmount)) AS ?totalRebalance)
           (MAX(xsd:decimal(?riskScore)) AS ?riskScore) WHERE {
      ?investor rdf:type wm:Investor .
      ?investor wm:investorId ?investorId .

      OPTIONAL {
        ?cf rdf:type wm:CashFlow .
        ?cf wm:investorId ?investorId .
        ?cf wm:amount ?cfAmount .
      }

      OPTIONAL {
        ?hold rdf:type wm:PortfolioHolding .
        ?hold wm:investorId ?investorId .
        ?hold wm:cost ?cost .
        ?hold wm:currentValue ?curr .
        FILTER(bound(?cost) && bound(?curr))
        BIND((xsd:decimal(?curr) - xsd:decimal(?cost)) AS ?gain)
      }

      OPTIONAL {
        ?reb rdf:type wm:RebalancingAction .
        ?reb wm:investorId ?investorId .
        ?reb wm:amount ?rebAmount .
      }

      OPTIONAL {
        ?ph rdf:type wm:PortfolioHealth .
        ?ph wm:investorId ?investorId .
        ?ph wm:riskScore ?riskScore .
      }
    }
    GROUP BY ?investorId
    HAVING (BOUND(?totalCashFlow) && BOUND(?totalHoldingGain) && BOUND(?totalRebalance) && BOUND(?riskScore))
  }

  # global min / max for each component
  {
    SELECT (MIN(?totalCashFlow) AS ?minCash) (MAX(?totalCashFlow) AS ?maxCash)
           (MIN(?totalHoldingGain) AS ?minGain) (MAX(?totalHoldingGain) AS ?maxGain)
           (MIN(?totalRebalance) AS ?minReb) (MAX(?totalRebalance) AS ?maxReb)
           (MIN(?riskScore) AS ?minRisk) (MAX(?riskScore) AS ?maxRisk) WHERE {
      {
        SELECT ?investorId
               (SUM(xsd:decimal(?cfAmount)) AS ?totalCashFlow)
               (SUM(xsd:decimal(?gain)) AS ?totalHoldingGain)
               (SUM(xsd:decimal(?rebAmount)) AS ?totalRebalance)
               (MAX(xsd:decimal(?riskScore)) AS ?riskScore) WHERE {
          ?investor rdf:type wm:Investor .
          ?investor wm:investorId ?investorId .

          OPTIONAL {
            ?cf rdf:type wm:CashFlow .
            ?cf wm:investorId ?investorId .
            ?cf wm:amount ?cfAmount .
          }

          OPTIONAL {
            ?hold rdf:type wm:PortfolioHolding .
            ?hold wm:investorId ?investorId .
            ?hold wm:cost ?cost .
            ?hold wm:currentValue ?curr .
            FILTER(bound(?cost) && bound(?curr))
            BIND((xsd:decimal(?curr) - xsd:decimal(?cost)) AS ?gain)
          }

          OPTIONAL {
            ?reb rdf:type wm:RebalancingAction .
            ?reb wm:investorId ?investorId .
            ?reb wm:amount ?rebAmount .
          }

          OPTIONAL {
            ?ph rdf:type wm:PortfolioHealth .
            ?ph wm:investorId ?investorId .
            ?ph wm:riskScore ?riskScore .
          }
        }
        GROUP BY ?investorId
        HAVING (BOUND(?totalCashFlow) && BOUND(?totalHoldingGain) && BOUND(?totalRebalance) && BOUND(?riskScore))
      }
    }
  }

  # normalization and composite score
  BIND( IF(?maxCash != ?minCash, ( ?totalCashFlow - ?minCash ) / ( ?maxCash - ?minCash ), 0) AS ?normCash )
  BIND( IF(?maxGain != ?minGain, ( ?totalHoldingGain - ?minGain ) / ( ?maxGain - ?minGain ), 0) AS ?normGain )
  BIND( IF(?maxReb != ?minReb, ( ?totalRebalance - ?minReb ) / ( ?maxReb - ?minReb ), 0) AS ?normReb )
  BIND( IF(?maxRisk != ?minRisk, ( ?riskScore - ?minRisk ) / ( ?maxRisk - ?minRisk ), 0) AS ?normRisk )
  BIND( ( ( ?normCash + ?normGain + ?normReb + ?normRisk ) / 4 ) * 100 AS ?compositeScore )
}
ORDER BY DESC(?compositeScore) ASC(?investorId)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?segment
WHERE {
  ?investor rdf:type wm:Investor .
  OPTIONAL { ?investor wm:investorId ?investorId . }
  OPTIONAL { ?investor wm:investorName ?investorName . }
  OPTIONAL { ?investor wm:segment ?segment . }
  FILTER (BOUND(?segment) && (LCASE(?segment) NOT IN ("diversified","large cap","mid cap","small cap")))
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
