               LCASE(?horizon) = "medium-term" ||
               LCASE(?horizon) = "short-term" ) )
  ?cashFlow rdf:type wm:CashFlow .
  ?cashFlow wm:cashFlowOfInvestor ?investor .
  OPTIONAL { ?cashFlow wm:cashFlowId ?cashFlowId . }
  OPTIONAL { ?cashFlow wm:amount ?amount . }
  OPTIONAL { ?cashFlow wm:date ?date . }
  OPTIONAL { ?cashFlow wm:source ?source . }
  OPTIONAL { ?cashFlow wm:notes ?notes . }
  OPTIONAL { ?cashFlow wm:investorId ?investorId . }
}

