  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:investorName ?investorName . }

  # Investor has at least one portfolio holding
  FILTER EXISTS {
    ?investor wm:hasHolding ?holding .
    ?holding rdf:type wm:PortfolioHolding .
  }

  # Investor does NOT have a rebalancing action
  FILTER NOT EXISTS {
    ?investor wm:hasRebalancingAction ?rebalance .
    ?rebalance rdf:type wm:RebalancingAction .
  }
}

