PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?goalId ?description ?progressPct
WHERE {
  ?goal rdf:type wm:InvestmentGoal .
  OPTIONAL { ?goal wm:goalId ?goalId . }
  OPTIONAL { ?goal wm:description ?description . }
  OPTIONAL {
    ?goal wm:progressPct ?progressRaw .
    BIND(xsd:decimal(?progressRaw) AS ?progressPct)
  }
}
ORDER BY DESC(?progressPct)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance (AVG(xsd:decimal(?investorAvgSharpe)) AS ?averageSharpeRatio)
WHERE {
  {
    SELECT ?investorId (COALESCE(?riskTol, "NULL") AS ?riskTolerance) (AVG(xsd:decimal(?goalSharpe)) AS ?investorAvgSharpe)
    WHERE {
      ?investor rdf:type wm:Investor .
      OPTIONAL { ?investor wm:investorId ?investorId . }
      OPTIONAL { ?investor wm:riskTolerance ?riskTol . }
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?investor .
      OPTIONAL { ?goal wm:avgSharpeRatio ?goalSharpe . }
    }
    GROUP BY ?investorId ?riskTol
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTol (AVG(xsd:decimal(?invAvgProgress)) AS ?averageGoalProgress) WHERE {
  {
    SELECT ?investor ?riskTol (AVG(xsd:decimal(?progressPct)) AS ?invAvgProgress) WHERE {
      ?investor rdf:type wm:Investor .
      OPTIONAL { ?investor wm:riskTolerance ?riskTol . }
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?investor .
      ?goal wm:progressPct ?progressPct .
    }
    GROUP BY ?investor ?riskTol
  }
  BIND(COALESCE(?riskTol, "NULL") AS ?riskTol)
}
GROUP BY ?riskTol

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance (AVG(xsd:decimal(?investorAvgReturn)) AS ?avgAnnualReturnByRiskTolerance)
WHERE {
  {
    SELECT ?investorId (AVG(xsd:decimal(?goalReturn)) AS ?investorAvgReturn) WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:avgAnnualReturnPct ?goalReturn .
      ?goal wm:belongsToInvestor ?investor .
      ?investor wm:investorId ?investorId .
    } GROUP BY ?investorId
  }
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:riskTolerance ?riskTolerance . }
  BIND (COALESCE(?riskTolerance, "NULL") AS ?riskTolerance)
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?avgReturn WHERE {
  {
    SELECT ?inv (AVG(xsd:decimal(?annualReturn)) AS ?avgReturn) WHERE {
      ?ig rdf:type wm:InvestmentGoal .
      ?ig wm:belongsToInvestor ?inv .
      ?ig wm:avgAnnualReturnPct ?annualReturn .
    }
    GROUP BY ?inv
  }
  ?inv rdf:type wm:Investor .
  OPTIONAL { ?inv wm:investorId ?investorId . }
  OPTIONAL { ?inv wm:investorName ?investorName . }
  ?ph rdf:type wm:PortfolioHealth .
  ?ph wm:healthOfInvestor ?inv .
  ?ph wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) > 50)
}
ORDER BY DESC(?avgReturn)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskToleranceLabel (AVG(xsd:decimal(?avgAnnualReturn)) AS ?averageAnnualReturnPct)
WHERE {
  ?investor rdf:type wm:Investor .
  ?ph rdf:type wm:PortfolioHealth ;
      wm:healthOfInvestor ?investor ;
      wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) > 50) .

  ?ig rdf:type wm:InvestmentGoal ;
      wm:belongsToInvestor ?investor ;
      wm:avgAnnualReturnPct ?avgAnnualReturn .

  OPTIONAL {
    ?investor wm:hasRiskTolerance ?rt .
    ?rt rdfs:label ?riskToleranceLabel .
  }
  BIND(COALESCE(?riskToleranceLabel, "NULL") AS ?riskToleranceLabel)
}
GROUP BY ?riskToleranceLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segmentLabel (AVG(xsd:decimal(?sharpe)) AS ?avgSharpeRatio)
WHERE {
  ?investor rdf:type wm:Investor .
  ?ph rdf:type wm:PortfolioHealth .
  ?ph wm:healthOfInvestor ?investor ;
      wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) > 50) .

  OPTIONAL { ?investor wm:segment ?segmentLiteral . }
  OPTIONAL {
    ?investor wm:hasSegment ?segment .
    ?segment rdfs:label ?segLabel .
  }
  BIND(COALESCE(?segLabel, ?segmentLiteral, "NULL") AS ?segmentLabel) .

  ?goal rdf:type wm:InvestmentGoal ;
        wm:belongsToInvestor ?investor ;
        wm:avgSharpeRatio ?sharpe .
}
GROUP BY ?segmentLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon (AVG(xsd:decimal(?sharpeRatio)) AS ?avgSharpeRatio)
WHERE {
  ?investor rdf:type wm:Investor .
  ?ph rdf:type wm:PortfolioHealth ;
      wm:healthOfInvestor ?investor ;
      wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) > 50) .

  OPTIONAL { ?investor wm:timeHorizon ?timeHorizon . }
  OPTIONAL {
    ?investor wm:hasInvestmentGoal ?goal .
    ?goal rdf:type wm:InvestmentGoal ;
          wm:avgSharpeRatio ?sharpeRatio .
  }
  FILTER(BOUND(?sharpeRatio) && BOUND(?timeHorizon))
}
GROUP BY ?timeHorizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?avgGoalProgress ?avgHoldingReturn ?riskScore WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:investorName ?investorName . }
  OPTIONAL { ?investor wm:segment ?segment . }
  FILTER(BOUND(?segment) && LCASE(STR(?segment)) = "aggressive") .

  # Risk score from PortfolioHealth
  OPTIONAL {
    ?health rdf:type wm:PortfolioHealth .
    ?health wm:healthOfInvestor ?investor .
    ?health wm:riskScore ?riskScore .
  }
  FILTER(BOUND(?riskScore) && xsd:decimal(?riskScore) > 50) .

  # Average InvestmentGoal progressPct per investor
  {
    SELECT ?investor (AVG(xsd:decimal(?progressPct)) AS ?avgGoalProgress) WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?investor .
      ?goal wm:progressPct ?progressPct .
    } GROUP BY ?investor
  }
  FILTER(BOUND(?avgGoalProgress) && xsd:decimal(?avgGoalProgress) < 30) .

  # Average holding returnsPct for holdings with cost and currentValue
  {
    SELECT ?investor (AVG(xsd:decimal(?returnsPct)) AS ?avgHoldingReturn) WHERE {
      ?holding rdf:type wm:PortfolioHolding .
      ?holding wm:heldByInvestor ?investor .
      ?holding wm:returnsPct ?returnsPct .
      ?holding wm:cost ?cost .
      ?holding wm:currentValue ?currentValue .
      FILTER(BOUND(?cost) && BOUND(?currentValue))
    } GROUP BY ?investor
  }
  FILTER(BOUND(?avgHoldingReturn) && xsd:decimal(?avgHoldingReturn) > 50) .
}
ORDER BY ?investorId

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?avgGoalProgress ?avgDividends WHERE {
  # Investors with goal-match > 50
  ?ph rdf:type wm:PortfolioHealth .
  ?ph wm:healthOfInvestor ?investor .
  ?ph wm:goalMatchPct ?goalMatchPct .
  FILTER(xsd:decimal(?goalMatchPct) > 50) .
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:investorName ?investorName . }

  # Average goal progress per investor
  {
    SELECT ?investor (AVG(xsd:decimal(?progressPct)) AS ?avgGoalProgress) WHERE {
      ?investor wm:hasInvestmentGoal ?goal .
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:progressPct ?progressPct .
    } GROUP BY ?investor
  }

  # Average holding dividends per investor
  {
    SELECT ?investor (AVG(xsd:decimal(?dividends)) AS ?avgDividends) WHERE {
      ?holding rdf:type wm:PortfolioHolding .
      ?holding wm:heldByInvestor ?investor .
      ?holding wm:dividends ?dividends .
    } GROUP BY ?investor
  }
}
ORDER BY ?avgGoalProgress
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon (AVG(xsd:decimal(?returnsPct)) AS ?avgHoldingReturn)
WHERE {
  {
    SELECT ?investor ?timeHorizon
    WHERE {
      ?investor rdf:type wm:Investor .
      OPTIONAL { ?investor wm:timeHorizon ?timeHorizon . }
      OPTIONAL {
        ?investor wm:hasInvestmentGoal ?goal .
        ?goal wm:progressPct ?progress .
      }
      OPTIONAL {
        ?investor wm:hasPortfolioHealth ?ph .
        ?ph wm:riskScore ?riskScore .
      }
    }
    GROUP BY ?investor ?timeHorizon
    HAVING (AVG(xsd:decimal(?progress)) > 30 && MAX(xsd:decimal(?riskScore)) > 50)
  }
  ?investor wm:hasHolding ?holding .
  ?holding wm:returnsPct ?returnsPct .
  ?holding wm:cost ?cost .
  ?holding wm:currentValue ?currentValue .
  FILTER (bound(?cost) && bound(?currentValue))
}
GROUP BY ?timeHorizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName WHERE {
  ?inv rdf:type wm:Investor .
  ?inv wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }
  ?inv wm:riskTolerance ?riskTol .
  FILTER(CONTAINS(LCASE(STR(?riskTol)), "aggressive"))

  {
    SELECT ?investorId (AVG(xsd:decimal(?sharpe)) AS ?avgSharpe) WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:investorId ?investorId .
      ?goal wm:avgSharpeRatio ?sharpe .
    } GROUP BY ?investorId
    HAVING (AVG(xsd:decimal(?sharpe)) > 0.0)
  }

  {
    SELECT ?investorId (AVG(xsd:decimal(?div)) AS ?avgDiv) WHERE {
      ?hold rdf:type wm:PortfolioHolding .
      ?hold wm:investorId ?investorId .
      ?hold wm:dividends ?div .
    } GROUP BY ?investorId
    HAVING (AVG(xsd:decimal(?div)) > 14000)
  }

  {
    SELECT ?investorId ?goalMatchPct WHERE {
      ?ph rdf:type wm:PortfolioHealth .
      ?ph wm:investorId ?investorId .
      ?ph wm:goalMatchPct ?goalMatchPct .
    } FILTER(xsd:decimal(?goalMatchPct) > 50)
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?avgGoalProgress ?avgDividends WHERE {
  {
    SELECT ?investorId ?investorName (AVG(xsd:decimal(?progressPct)) AS ?avgGoalProgress) WHERE {
      ?inv rdf:type wm:Investor .
      ?inv wm:investorId ?investorId .
      OPTIONAL { ?inv wm:investorName ?investorName . }
      ?ph rdf:type wm:PortfolioHealth .
      ?ph wm:healthOfInvestor ?inv .
      ?ph wm:goalMatchPct ?goalMatchPct .
      FILTER(xsd:decimal(?goalMatchPct) > 50) .
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?inv .
      ?goal wm:progressPct ?progressPct .
    } GROUP BY ?investorId ?investorName
  }
  {
    SELECT ?investorId (AVG(xsd:decimal(?dividends)) AS ?avgDividends) WHERE {
      ?inv2 rdf:type wm:Investor .
      ?inv2 wm:investorId ?investorId .
      ?hold rdf:type wm:PortfolioHolding .
      ?hold wm:heldByInvestor ?inv2 .
      ?hold wm:dividends ?dividends .
    } GROUP BY ?investorId
  }
}
ORDER BY DESC(?avgGoalProgress)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:investorName ?investorName . }
  ?investor wm:riskTolerance ?riskTol .
  FILTER(CONTAINS(LCASE(STR(?riskTol)), "conservative"))

  ?ph rdf:type wm:PortfolioHealth .
  ?ph wm:healthOfInvestor ?investor .
  ?ph wm:liquidityScore ?liqScore .
  FILTER(xsd:decimal(?liqScore) < 50)

  {
    SELECT ?investor (AVG(xsd:decimal(?progressPct)) AS ?avgProgress) WHERE {
      ?goal rdf:type wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?investor .
      ?goal wm:progressPct ?progressPct .
    } GROUP BY ?investor
    HAVING (AVG(xsd:decimal(?progressPct)) > 30)
  }

  {
    SELECT ?investor (AVG(xsd:decimal(?dividends)) AS ?avgDiv) WHERE {
      ?holding rdf:type wm:PortfolioHolding .
      ?holding wm:heldByInvestor ?investor .
      ?holding wm:dividends ?dividends .
    } GROUP BY ?investor
    HAVING (AVG(xsd:decimal(?dividends)) < 14000)
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?totalCashFlow WHERE {
  ?investor rdf:type wm:Investor .
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:investorName ?investorName . }
  ?investor wm:riskTolerance ?riskTol .
  FILTER(CONTAINS(LCASE(STR(?riskTol)), "aggressive"))

  FILTER EXISTS {
    ?goal rdf:type wm:InvestmentGoal .
    ?goal wm:belongsToInvestor ?investor .
    ?goal wm:shortfall ?shortfall .
    FILTER(xsd:decimal(?shortfall) > 0)
  }

  {
    SELECT ?investor (SUM(xsd:decimal(?amount)) AS ?totalCashFlow) WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?investor .
      ?cf wm:amount ?amount .
    } GROUP BY ?investor
  }
}
ORDER BY DESC(?totalCashFlow)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (AVG(xsd:decimal(?amount)) AS ?averageNetCashFlow)
WHERE {
  ?investor rdf:type wm:Investor .
  ?sectorAlloc rdf:type wm:SectorAllocation ;
               wm:allocationOfInvestor ?investor ;
               wm:allocationPct ?allocPct ;
               wm:hasSector ?sector .
  FILTER(xsd:decimal(?allocPct) > 0) .
  ?sector rdfs:label ?sectorLabel .
  FILTER(LCASE(STR(?sectorLabel)) = "consumer goods") .

  ?cashFlow rdf:type wm:CashFlow ;
            wm:cashFlowOfInvestor ?investor ;
            wm:amount ?amount .
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (AVG(xsd:decimal(?totalCashFlow)) AS ?averageNetCashFlow) WHERE {
  {
    SELECT ?investor (SUM(xsd:decimal(?amount)) AS ?totalCashFlow) WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?investor .
      ?cf wm:amount ?amount .
    }
    GROUP BY ?investor
  }
  FILTER EXISTS {
    ?sa rdf:type wm:SectorAllocation .
    ?sa wm:allocationOfInvestor ?investor .
    ?sa wm:sector ?sector .
    ?sa wm:allocationPct ?allocPct .
    FILTER(LCASE(STR(?sector)) = "corporate") .
    FILTER(xsd:decimal(?allocPct) > 0) .
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName WHERE {
  ?inv rdf:type wm:Investor .
  ?inv wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }
  ?inv wm:riskTolerance ?riskTol .
  FILTER(LCASE(STR(?riskTol)) = "conservative") .

  FILTER EXISTS {
    ?goal rdf:type wm:InvestmentGoal .
    ?goal wm:belongsToInvestor ?inv .
    ?goal wm:shortfall ?shortfall .
    FILTER(xsd:decimal(?shortfall) > 0)
  }

  {
    SELECT ?inv (SUM(xsd:decimal(?amount)) AS ?totalCash) WHERE {
      ?cf rdf:type wm:CashFlow .
      ?cf wm:cashFlowOfInvestor ?inv .
      ?cf wm:amount ?amount .
      ?cf wm:date ?date .
      FILTER(STRSTARTS(STR(?date), "2025"))
    } GROUP BY ?inv
  }
  FILTER(xsd:decimal(?totalCash) < 0)
}
